insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('pia', 'intermediate', 'module', 'm01-the-small-field-tranches', 1, 'A shallow water field produces 50,000 bopd of crude oil. What liquids royalty rate does the engine return on the whole volume?', '["12.5 percent on every barrel, the shallow water terrain rate of para 10(2)(b) once past 10,000 bopd", "0.132500, the three bands with the upper one at 15 percent", "0.112500, one weighted rate built from the 5, 7.5 and 12.5 percent bands", "0.062500, the average of the two small-field tranches"]'::jsonb, 2, 'The Regulations'' r.13(2)(d) weights 5 percent on the first 5,000 bopd, 7.5 percent on the next 5,000 and 12.5 percent on the rest, divided by the whole daily volume, and the engine returns 0.112500 at 50,000 bopd in shallow water. Charging 12.5 percent on every barrel ignores the tranches the proviso keeps for the first 10,000 bopd. 0.132500 is the onshore figure at the same daily rate, where the upper band is 15 percent. 0.062500 is the rate at exactly 10,000 bopd, and a larger field pays more than that.'),
  ('pia', 'intermediate', 'module', 'm01-the-small-field-tranches', 2, 'A deep offshore field produces 60,000 bopd. Which rate does the engine apply to its crude oil and condensate value?', '["0.054167, since only the barrels past 50,000 bopd pay 7.5 percent", "7.5 percent on the whole volume, because the field has stepped over the 50,000 bopd tier and lost it", "0.050000, since the deep offshore tier covers every barrel up to 120000 bopd", "0.114583, the shallow water weighting at that daily rate"]'::jsonb, 0, 'Para 10(3) charges 5 percent up to 50,000 bopd and the terrain rate on "the share of the production above 50,000 bopd", and r.13(1)(b) makes that one weighted average, so 60,000 bopd returns 0.054167. Charging 7.5 percent on every barrel treats the tier as a step, which the text does not do. The 5 percent tier stops at 50,000 bopd, so 0.050000 is wrong past it. 0.114583 is the shallow water return at 60,000 bopd and belongs to a different terrain.'),
  ('pia', 'intermediate', 'module', 'm01-the-small-field-tranches', 3, 'Ekene Alpha produces 2920000 bbl of oil and 116800 bbl of condensate in 2026 and the engine prints a daily rate of 8320.000000 bopd. What produced that figure?', '["Only the crude oil over 365 days, condensate going to gas", "Each month''s liquids over that month''s producing days", "Oil, condensate and gas in oil equivalent, over the year", "Crude oil plus condensate for the year, over its 365 calendar days"]'::jsonb, 3, 'Para 6 treats condensate as crude oil for royalty, r.12(1)(b) applies the scale to crude oil plus condensate, and the engine divides the year''s total by the calendar days (365 in 2026). Leaving condensate out would understate the rate; condensate is never moved to the gas royalty. The month-by-month division is the Regulations'' own r.12(2), which the engine replaces with an annual reading and says so in its notes. Gas stays out of the daily rate entirely.'),
  ('pia', 'intermediate', 'module', 'm01-the-small-field-tranches', 4, 'Ekene Alpha declines to 4989.463014 bopd in 2030. What liquids royalty rate does the engine return that year?', '["0.050005, since a slice past the first edge still pays 7.5 percent", "0.050000, the first tranche alone", "0.075000, the flat rate a small shallow water field falls back to", "0.062500, the average of the two small-field tranches of para 10(4)"]'::jsonb, 1, 'At or below 5,000 bopd the Regulations'' r.13(2)(a) gives 5 percent, and the engine returns exactly 0.050000 for Alpha from 2030. 0.050005 is the return at 5001 bopd, one barrel past the edge, and Alpha is below it. 0.075000 is the frontier rate, which has no sliding scale and has nothing to do with a small shallow water field. 0.062500 is the rate at exactly 10,000 bopd, where half the volume pays 7.5 percent.'),
  ('pia', 'intermediate', 'module', 'm01-the-small-field-tranches', 5, 'The Regulations'' r.13(2)(b) covers "greater than 5,000bopd but less than 10,000bopd" and r.13(2)(c) covers "greater than 10,000bopd". What does the engine return for an onshore field at exactly 10,000 bopd?', '["A refusal, because a daily rate that neither band names leaves the engine with no formula it can apply", "0.062500, which each formula gives at that point, so the gap moves no figure", "0.062509, reading the edge into the onshore upper band", "0.075000, a flat rate for a volume both bands omit"]'::jsonb, 1, 'Neither band names exactly 10,000 bopd, but both formulas give 0.062500 there from the stated tranches, and that is the engine''s return; the edge belongs to the tranche below it. 0.062509 is the onshore return at 10001 bopd, one barrel into the upper band. The engine does not refuse a daily rate of 0 or more. 0.075000 is the frontier rate and plays no part in the onshore scale.'),
  ('pia', 'intermediate', 'module', 'm01-the-small-field-tranches', 6, 'Over which daily rates do an onshore and a shallow water field pay the same liquids royalty rate?', '["At every daily rate, since terrain moves the tax rate alone", "Only at or below 5,000 bopd, inside the first tranche", "Only above 10,000 bopd, where both use three bands", "At or below 10,000 bopd"]'::jsonb, 3, 'Both tranches of para 10(4) are common to onshore and shallow water, so up to and including 10,000 bopd the two pay the same rate (0.058333 at 7500 bopd, 0.062500 at 10,000). Above it the terrain rate enters, 15 percent onshore against 12.5 percent in shallow water, so at 20000 bopd the returns are 0.106250 and 0.093750. The second tranche is shared too, so the agreement does not stop at 5,000 bopd. Terrain does move royalty above 10,000 bopd.'),
  ('pia', 'intermediate', 'module', 'm01-the-small-field-tranches', 7, 'At 10001 bopd the engine returns 0.062509 onshore and 0.062506 in shallow water. Why do the two terrains part at that point?', '["The barrel past 10,000 bopd pays the terrain rate, 15 percent onshore and 12.5 percent in shallow water", "Shallow water keeps its second tranche running on past 10,000 bopd, where the onshore one stops", "Onshore fields lose their first tranche above 10,000 bopd, so every onshore barrel pays 7.5 percent or more", "The engine divides onshore volumes by 366 days and offshore volumes by 365, so the daily rates differ"]'::jsonb, 0, 'The proviso to para 10(4) charges "the share of the production over 10,000 bopd" at the subparagraph (2) terrain rate, and r.13(2)(c) and (d) put 15 percent onshore and 12.5 percent in shallow water on that incremental volume, so the onshore rate rises faster. Neither terrain loses the first tranche; the Regulations keep 5 percent on 5,000 bopd in every band. The second tranche ends at 10,000 bopd on both terrains. The day count depends on the year and never on the terrain.'),
  ('pia', 'intermediate', 'module', 'm01-the-small-field-tranches', 8, 'A frontier field produces 20000 bopd. What liquids royalty rate does the engine return?', '["0.050000, the deep offshore tier", "0.093750, the shallow water weighting lent to every frontier basin", "0.075000, flat, with no sliding scale", "0.106250, the onshore weighting, as frontier acreage lies on land"]'::jsonb, 2, 'The Regulations'' r.13(3) says: "(3) For frontier basin, the sliding scale shall not apply and the applicable rate shall be 7.5%." The engine returns 0.075000 at every daily rate on frontier. The 5 percent tier belongs to deep offshore alone. 0.093750 and 0.106250 are the shallow water and onshore returns at 20000 bopd; frontier borrows neither scale.'),
  ('pia', 'intermediate', 'module', 'm01-the-small-field-tranches', 9, 'A deep offshore field at 50001 bopd prints the same six-decimal rate, 0.050000, as one at 50,000 bopd. What explains it?', '["The deep offshore tier runs on to 60,000 bopd, so the extra barrel still pays 5 percent", "The engine rounds each daily rate down to whole thousands before any tier", "Para 10(3) reads its limit monthly, so one extra barrel a day goes free", "One barrel at 7.5 percent moves the weighted rate by less than six decimals show"]'::jsonb, 3, 'At or below 50,000 bopd the rate is exactly 5 percent; above it only the barrels past 50,000 pay 7.5 percent, and one barrel in 50001 lifts the weighted rate by less than the course''s six decimals. The tier ends at 50,000 bopd, as the 60000 bopd return of 0.054167 shows. The engine does not round the daily rate to thousands; Alpha''s 2026 rate is 8320.000000. The monthly wording is a reading of the day count and exempts no barrel from the rate.'),
  ('pia', 'intermediate', 'module', 'm01-the-small-field-tranches', 10, 'A field produces crude oil, condensate and natural gas liquids. Under PIA Seventh Schedule para 6, which volumes enter the daily rate the tranches read?', '["Crude oil and condensate, with the natural gas liquids treated as natural gas", "Only the crude oil, since the tranches are written for barrels of crude oil and nothing else", "All three liquids, each measured in barrels at the measurement point", "Oil and natural gas liquids, condensate left out"]'::jsonb, 0, 'Para 6 says that "for royalty purposes condensates shall be treated as crude oil and natural gas liquids shall be treated as natural gas." So condensate joins crude oil in the daily rate and the tranche rate, and natural gas liquids pay the gas royalty. Leaving condensate out, or counting the natural gas liquids in, each misreads that sentence.'),
  ('pia', 'intermediate', 'module', 'm01-the-small-field-tranches', 11, 'Ekene Alpha''s 2028 daily rate prints as 6425.404372 bopd. Which day count did the engine divide the year''s crude oil plus condensate by?', '["365 in every year, a fixed length for the royalty tranches", "The days oil was produced in each month, month by month as r.12(2) directs", "366, the calendar days of 2028", "The producing days of 2028 as a whole"]'::jsonb, 2, 'The engine divides by the calendar days of the year, and 2028 is a leap year of 366 days, so the rate is 6425.404372 and the liquids royalty rate 0.055546. A fixed 365 would miss the leap day. Dividing by the days oil flowed, month by month or over the year, is the Regulations'' method; the engine reads the calendar year and states that choice in its notes.'),
  ('pia', 'intermediate', 'module', 'm01-the-small-field-tranches', 12, 'Every PIA run of the engine prints this note: "Royalty tranches read the year''s crude oil plus condensate divided by the calendar days of the year; the Regulations (r.12(2)) divide each month''s production by the days oil was produced in that month." What is the note?', '["A refusal, cleared by loading twelve monthly production rows for every year of the ledger", "A statement of the engine''s annual reading attached to a finished result", "A warning that the liquids royalty for the year was left out of the ledger it returns", "A stated default to switch off before the figures can be used"]'::jsonb, 1, 'A note in kpis.pia_notes is part of a result: the ledger ran, and the engine states where its annual day count departs from the monthly method of r.12(2). A refusal is a thrown error and no result comes back. The liquids royalty is computed on every row. The note names no switch to turn off; the annual reading is how the engine computes the daily rate.'),
  ('pia', 'intermediate', 'module', 'm01-the-small-field-tranches', 13, 'A field lies partly onshore and partly in shallow water. Para 10(7) says its "weighted average royalty shall be calculated as per regulations." What does the engine do with such a field?', '["It runs one stated terrain string at a time and never reads the water depth", "It splits the field at the 200 metre line using pia_water_depth_m", "It weights the two rates by a stated production share", "It refuses the run until the depth field is removed"]'::jsonb, 0, 'The engine takes the terrain as one of four strings and carries pia_water_depth_m without reading it, so a straddling field is run under one terrain at a time and the Regulations'' weighting of r.14(5) stays outside the engine. That is why the provision is concept-only and never graded on a number. There is no share-of-production input, and the engine does not refuse a run because a depth is present.'),
  ('pia', 'intermediate', 'module', 'm01-the-small-field-tranches', 14, 'A field''s weighted liquids royalty rate falls. Which hydrocarbon tax line does that raise directly, and under which provision?', '["The cost price ratio cap, with royalties claimed inside the 65 percent limit of the Sixth Schedule", "The s.267 hydrocarbon tax rate, which the Act sets higher for a field paying the low tranches", "The production allowance paid on the barrels", "The assessable profit, since royalties are deducted under s.263(1)(b)"]'::jsonb, 3, 'PIA s.263(1)(b) deducts "all royalties the liability for which was incurred and were paid by the company during that period in respect of crude oil and associated gas", so a smaller royalty leaves more assessable profit. Royalties sit outside the cost price ratio (para 2(1) excludes s.263(1)(b)), and the cap is measured on revenue alone. The s.267 rate depends on licence and lease. The production allowance is a sum per barrel that no royalty changes.'),
  ('pia', 'intermediate', 'module', 'm01-the-small-field-tranches', 15, 'The Ekene marginal field is a shallow water lease converted under s.94(1), producing 20000 bopd in 2026. What liquids royalty rate does the engine return?', '["0.150000, the rate that s.94(1) attaches to a converted producing marginal field", "0.050000, the first tranche on every barrel of a marginal field", "0.093750, the shallow water tranches", "0.106250, the onshore weighting applied to every marginal field"]'::jsonb, 2, 'The marginal field flag moves the hydrocarbon tax rate to 0.150000; the royalty follows the terrain''s tranches, and at 20000 bopd in shallow water that is 0.093750. So 0.150000 is the tax rate, which is a different line. Para 10(4) names marginal fields inside the same onshore and shallow water tranches, with no special first-tranche rule. 0.106250 is the onshore figure at 20000 bopd; this lease is in shallow water.'),
  ('pia', 'intermediate', 'module', 'm02-what-the-hydrocarbon-tax-charges', 1, 'PIA s.260(1)(a) says what the hydrocarbon tax applies to. Which streams does it name?', '["Every hydrocarbon the field sells, gas included, measured at the measurement points", "Crude oil, field condensates, and liquid natural gas liquids derived from associated gas", "Only the crude oil, with condensate handled by the gas royalty", "Crude oil and condensates from non-associated gas plants"]'::jsonb, 1, 'The text reads: "(a) hydrocarbon tax shall apply to crude oil as well as field condensates and liquid natural gas liquids derived from associated gas and produced in the field upstream of the measurement points ;". Gas itself is outside the tax, so a scope of every hydrocarbon sold is too wide. Condensate is named in the scope, so crude oil alone is too narrow. Condensates and natural gas liquids from non-associated gas are taken out by s.260(1)(b)(ii), a concept-only line in this course.'),
  ('pia', 'intermediate', 'module', 'm02-what-the-hydrocarbon-tax-charges', 2, 'The Ekene gas field (shallow water, converted lease, no crude oil or condensate) returns a cost price ratio cap of 0.000000 and a hydrocarbon tax of 0.000000 in 2026. Why?', '["Gas used in-country at 2.5 percent royalty is exempted from the hydrocarbon tax by the Seventh Schedule", "The gas royalty of 2250000.000000 is set off against the hydrocarbon tax until the tax reaches zero", "Any in-country gas share above zero exempts the lease", "It has no crude oil or condensate revenue, and gas sits outside the tax"]'::jsonb, 3, 'The engine charges the hydrocarbon tax on crude oil and condensate, and the cap is 65 percent of that revenue; with none, both are zero. The in-country share changes the gas royalty rate (0.037500 at half) and grants no exemption from any tax. A royalty is a deduction in a tax base and is never set off against the tax itself. The in-country share of 50 percent is accepted; a refusal would return no figures at all.'),
  ('pia', 'intermediate', 'module', 'm02-what-the-hydrocarbon-tax-charges', 3, 'On the Ekene gas field, which tax charges the 2026 gas profit, and at what figure?', '["Companies income tax, at 10713000.000000", "The hydrocarbon tax at the 30 percent class, on a base of 47710000.000000 once the gas royalty is deducted", "No profit tax at all, since the gas royalty of 0.037500 is the whole fiscal charge on gas in 2026", "A 15 percent hydrocarbon tax, the rate s.267(b) gives to a gas field in shallow water"]'::jsonb, 0, 'Gas revenue is outside the hydrocarbon tax, and companies income tax is charged on oil and gas together, so the gas profit carries companies income tax: an assessable profit of 47710000.000000 and a tax of 10713000.000000 in 2026. The 47710000.000000 figure is the companies income tax base and belongs to no hydrocarbon tax computation. The royalty is one instrument among several and leaves the profit taxable. Section 267 sets rates on profit from crude oil and gives no gas class.'),
  ('pia', 'intermediate', 'module', 'm02-what-the-hydrocarbon-tax-charges', 4, 'Ekene Alpha sells associated gas, and its liquids share of gross revenue is 0.970075 in 2026. Which of these enters its hydrocarbon tax at that share?', '["The cap, scaled down by 0.970075", "Both liquids royalties, the production royalty and the royalty by price, cut to the share by s.263(1)(b)", "Each cost shared with the gas: opex, the capital allowance, HCDT and the NDDC levy", "The rate, charged on the liquids share only"]'::jsonb, 2, 'The engine''s note says: "Opex, HCDT, NDDC, capital allowances and any decommissioning contribution enter the hydrocarbon tax at the crude-plus-condensate share of gross revenue." The cap is already 65 percent of crude oil and condensate revenue (147664400.000000 in 2026), so no share is applied to it. The liquids royalties are charged on liquids alone and deducted whole. The rate is 0.300000 on the chargeable profit; the share acts on shared costs.'),
  ('pia', 'intermediate', 'module', 'm02-what-the-hydrocarbon-tax-charges', 5, 'Why does the engine split Ekene Alpha''s shared costs by revenue share, and what does it say about that choice?', '["It cannot tell associated from non-associated gas, and it states the split in kpis.pia_notes as an approximation", "The Act orders costs split by revenue share in s.260(2), so the engine follows the text exactly and prints no note", "Costs are split by barrels of oil equivalent, which the Regulations prescribe for every gas field", "The split is a refusal the learner clears by stating which gas is associated"]'::jsonb, 0, 'Section 260(2) allocates associated gas costs to crude oil, and s.260(1)(b)(ii) takes non-associated gas condensate out of the tax. The engine carries one gas stream, so it uses the crude-plus-condensate share of gross revenue and says so in the sharedCosts note: "the engine cannot tell the two gases apart." The Act prescribes no revenue split, the engine uses revenue and never oil equivalent, and the run completes with a note, which is a result.'),
  ('pia', 'intermediate', 'module', 'm02-what-the-hydrocarbon-tax-charges', 6, 'The Ekene deep offshore lease has a 2025 hydrocarbon tax chargeable profit of 795646660.199557, in a year under the Act alone. What hydrocarbon tax does the engine charge that year?', '["30 percent of it, the s.267(a) rate for any petroleum mining lease", "15 percent of it, the s.267(b) rate for a lease out of new acreage", "0.000000, and no companies income tax on that profit either", "0.000000, since s.260(3) keeps deep offshore outside the Part"]'::jsonb, 3, 'PIA s.260(3) reads: "(3) This Part shall not apply to a frontier acreage until it is reclassified under section 68 (3) of this Act and to deep offshore." The engine returns a rate of 0.000000 and a tax of 0.000000, while still computing the base. Section 267 applies only where the Part applies. Companies income tax is charged on the same lease, 291253998.059867 in 2025.'),
  ('pia', 'intermediate', 'module', 'm02-what-the-hydrocarbon-tax-charges', 7, 'How does s.260(3) treat frontier acreage and deep offshore differently?', '["Both are outside the Part until their water depth is reclassified under s.68(3) by the Commission", "Frontier is outside the Part until reclassified under s.68(3); deep offshore is outside with no condition", "Only frontier paying royalty by price is outside; deep offshore only below 50,000 bopd", "Deep offshore is outside until reclassified; frontier is outside with no condition"]'::jsonb, 1, 'The text ties the reclassification condition to frontier acreage ("until it is reclassified under section 68 (3)") and names deep offshore at the end with no condition. The Nigeria Tax Act 2025 keeps the frontier carve-out in s.65(4). Water depth plays no part in the reclassification, frontier pays no royalty by price at all under para 11(2), and the 50,000 bopd tier is a royalty rule. The swapped reading reverses the two terrains.'),
  ('pia', 'intermediate', 'module', 'm02-what-the-hydrocarbon-tax-charges', 8, 'An onshore petroleum mining lease selected under s.93(6)(b) on conversion produces crude oil. What hydrocarbon tax rate does the engine return?', '["0.150000, as s.267(b) names onshore in its opening words", "0.000000, as a small onshore field pays royalty alone", "A refusal until a rate of 15 or 30 is stated", "0.300000, under s.267(a)"]'::jsonb, 3, 'Section 267(a) charges "30% of the profit from crude oil for petroleum mining leases selected under section 93 (6) (b) and (7) (b) of this Act with respect to onshore and shallow water areas", and the engine returns 0.300000 for a converted PML. Reading s.267(b) over every onshore lease skips the specific class (a) gives converted leases. The tranches are royalty and grant no tax holiday. The refusal applies to a lease granted out of new acreage, which this lease is not.'),
  ('pia', 'intermediate', 'module', 'm02-what-the-hydrocarbon-tax-charges', 9, 'Which of these returns a hydrocarbon tax rate of 0.150000 from the engine?', '["Any onshore petroleum mining lease converted from an oil mining lease", "An onshore petroleum prospecting licence", "A frontier lease of any size", "A shallow water converted lease producing above 10,000 bopd"]'::jsonb, 1, 'Section 267(b) gives 15 percent to "petroleum prospecting licences selected under section 93 (6) (a) and (7) (a)", and the engine returns 0.150000 for a PPL; a producing marginal field converted under s.94(1) gets the same. A converted PML pays 0.300000. Frontier acreage pays 0.000000 under s.260(3). The daily rate moves royalty and leaves the tax rate alone, so a large converted shallow water lease still pays 0.300000.'),
  ('pia', 'intermediate', 'module', 'm02-what-the-hydrocarbon-tax-charges', 10, 'Ekene Alpha is rerun with its licence type changed from "PML" to "PPL" and nothing else. What happens to its 2026 hydrocarbon tax lines?', '["Every line changes, since a prospecting licence has its own royalty tranches and its own cost price ratio", "It is refused: a PPL may not produce crude oil", "The rate and the tax change, and the assessable profit stays at 182041059.069891", "Nothing changes, since terrain alone sets the rate"]'::jsonb, 2, 'The licence type moves the s.267 class, so the rate drops to 0.150000 and the tax falls; the base (royalties, the cap, the allowances) does not read the licence, so the 2026 assessable profit stays at 182041059.069891. Royalty tranches and the cost price ratio take no licence input. The engine accepts "PML" or "PPL" and runs both. The rate is set by licence and lease status, and terrain alone would leave Alpha at 0.300000.'),
  ('pia', 'intermediate', 'module', 'm02-what-the-hydrocarbon-tax-charges', 11, 'What does PIA s.265(2) require of a company with profit in both classes of hydrocarbon tax rate?', '["A separate assessable profit for each of the two s.267 classes", "One profit, taxed at the average of 30 and 15 percent", "15 percent profits set against 30 percent losses", "Separate profits for each terrain the company works in"]'::jsonb, 0, 'Section 265(2) reads: "(2) The assessable profit shall be determined separately for each of the two classes of chargeable tax identified in section 267 (a) and (b)." The Nigeria Tax Act 2025 repeats it at s.70(2). There is no averaged rate, and keeping the classes apart means a loss in one is relieved in that class. The text separates by class of rate; terrain is a different axis.'),
  ('pia', 'intermediate', 'module', 'm02-what-the-hydrocarbon-tax-charges', 12, 'A new-acreage petroleum mining lease onshore is run with no pia_new_pml_hct_rate_pct. What does the engine return?', '["Tax at 30 percent, the engine''s default, with a note naming s.267(a)", "A result at 15 percent, the rate s.267(b) gives to every onshore lease", "The ledger, with the tax left blank and a note in kpis.pia_notes", "A refusal asking for the rate to be set to 15 or 30"]'::jsonb, 3, 'The engine''s own words: "A new-acreage petroleum mining lease onshore or in shallow water needs pia_new_pml_hct_rate_pct set to 15 or 30; got null." The text does not say which class such a lease falls in, so the rate is a stated input with no default, and a run without it is a thrown error. There is no default of 30 or of 15, and a refusal returns no ledger, blank or otherwise.'),
  ('pia', 'intermediate', 'module', 'm02-what-the-hydrocarbon-tax-charges', 13, 'The engine is given pia_new_pml_hct_rate_pct 20 on a new-acreage onshore lease. How does it respond?', '["Runs at 20 percent and names the stated rate in a note", "It rounds 20 to the nearest printed rate, 15, and carries on with that rate for every year of the ledger", "It refuses, and the first sentence of the message ends \"got 20.\"", "Accepted as an override, since any stated rate from 0 to 100 runs"]'::jsonb, 2, 'Only the two rates the text prints are accepted for the open reading, so 20 is refused with the same message as a missing rate, reading "got 20." where the other reads "got null." The engine never rounds a stated rate. The 0 to 100 range belongs to a different input, pia_hct_rate_override_pct, and the new-lease reading is not that input.'),
  ('pia', 'intermediate', 'module', 'm02-what-the-hydrocarbon-tax-charges', 14, 'The Ekene new onshore lease is run under both stated readings. Which 2026 figure differs between the two runs?', '["The hydrocarbon tax: 22711732.336957 stated 15 and 45423464.673913 stated 30", "The chargeable profit, which the stated rate reaches through the cost price ratio", "Companies income tax, lower under the stated 30 because it deducts the larger tax", "The production allowance, which is larger under the stated 15"]'::jsonb, 0, 'The stated rate moves the hydrocarbon tax line and nothing else: the 2026 chargeable profit is 151411548.913043 and companies income tax 50223464.673913 under both readings. The cost price ratio reads no rate. Companies income tax does not deduct the hydrocarbon tax (s.302(5)), so it is the same under both. The production allowance depends on lease status, terrain, price and cumulative barrels, none of which the rate touches.'),
  ('pia', 'intermediate', 'module', 'm02-what-the-hydrocarbon-tax-charges', 15, 'A learner types pia_gas_in_country_share_pct 120 into a ledger. What does the engine do?', '["It caps the share at 100 and prices all the gas at the 2.5 percent in-country rate", "It refuses: \"pia_gas_in_country_share_pct must be a number from 0 to 100; got 120.\"", "It reads the extra 20 as export gas and charges it the 5 percent royalty, with a note", "It runs and applies a gas rate below 0.025000"]'::jsonb, 1, 'The in-country share is a stated input from 0 to 100, and 120 is refused in the engine''s own words. The engine never caps or reinterprets a stated input; the fix is in the terms. At 100 the run is accepted and every unit of gas pays 0.025000, the floor of the blend, so no rate below it is possible.'),
  ('pia', 'intermediate', 'module', 'm03-deductions-and-the-cost-price-ratio', 1, 'Which of these deductions sits outside the 65 percent cost price ratio limit of the Sixth Schedule para 2(1)?', '["This year''s operating costs, at the crude-plus-condensate share", "The capital allowance the Fifth Schedule gives for the year", "The royalties, HCDT and the NDDC levy", "Cost carried in from last year"]'::jsonb, 2, 'Para 2(1) caps deductions "excluding those related to section 263 (1) (a), (b) and (h)": rents, royalties, and contributions to host communities development trusts, the NDDC and similar funds. Opex, the capital allowance and the carried pool are exactly what the cap claims from, so each of them sits inside it.'),
  ('pia', 'intermediate', 'module', 'm03-deductions-and-the-cost-price-ratio', 2, 'On the worked example inputs (shallow water, crude oil only, 2025) the cost price ratio cap is 949000000.000000 against gross revenue of 1,460,000,000.000000. What is the cap measured on?', '["Gross revenue from every stream, gas included", "Revenue after the liquids royalties", "The year''s total costs, 65 percent of them", "Crude oil and condensate revenue"]'::jsonb, 3, 'The cap is 65 percent of crude oil and condensate revenue, and on this crude-only year that is 949000000.000000. Gas revenue never enters the cap (the Ekene gas field''s cap is 0.000000). Royalties sit outside the cap and do not shrink its base. The limit is a share of revenue; a share of the costs would carry something forward every year.'),
  ('pia', 'intermediate', 'module', 'm03-deductions-and-the-cost-price-ratio', 3, 'When the engine fills the cost price ratio cap, in what order does it claim the pool?', '["This year''s capital allowance first, then opex, then the carried pool", "The carried pool and this year''s opex first, then this year''s capital allowance", "All three at once, pro rata to their size, until the cap is reached", "Opex first, then the capital allowance, with the carried pool claimed only after cessation"]'::jsonb, 1, 'The engine claims the carried pool and the year''s operating costs first and the year''s capital allowance last, so on a lease where the cap binds the capital allowance is the first thing carried forward. There is no pro rata split. A carried cost is claimed in any later year with room under the cap; at cessation what is still carried is forfeited.'),
  ('pia', 'intermediate', 'module', 'm03-deductions-and-the-cost-price-ratio', 4, 'On the Ekene CPR case the 2024 cap is 48750000.000000 and the claim equals it. What cost does the engine carry out of 2024?', '["21250000.000000, the part of the pool the cap turned away", "48750000.000000, the whole claim the cap let through that year", "75000000.000000, the 2024 gross revenue the cap is measured on", "5700000.000000, the NDDC levy, which the cap holds back"]'::jsonb, 0, 'The claim fills the cap at 48750000.000000 and what does not fit, 21250000.000000, is printed as CPR carried out and claimed in a later year. 48750000.000000 is what the cap let through. 75000000.000000 is 2024 gross revenue, the base of the cap. 5700000.000000 is the NDDC levy, which is deducted outside the cap and never carried.'),
  ('pia', 'intermediate', 'module', 'm03-deductions-and-the-cost-price-ratio', 5, 'On the Ekene CPR case the claim equals the cap in 2024, 2025 and 2026, yet the carried pool grows from 21250000.000000 to 52250000.000000 to 93000000.000000. Why does it grow?', '["Each year it waits, the carried cost earns a 65 percent uplift under para 2(2)(b) of the Sixth Schedule", "More opex and allowance arrive each year than the falling cap can take", "The whole 2024 capex is claimed again in every later year on top of the carry", "Royalties join the pool once the cap binds"]'::jsonb, 1, 'The cap is 65 percent of each year''s revenue: 48750000.000000, 39000000.000000, 29250000.000000 as revenue falls from 75000000.000000 to 45000000.000000. Each year 40000000 USD of opex and the year''s capital allowance on the 2024 spend arrive on top of the carried pool, more than even the 2024 cap takes, so the carry grows every year and grows faster as the cap falls. Para 2(2)(b) limits the carry to the cap and adds no uplift; para 2(2)(a) says the total deducted may not exceed the actual costs incurred. The capital allowance is a scheduled fraction of the spend each year, and no spend is claimed twice. Royalties stay outside the cap.'),
  ('pia', 'intermediate', 'module', 'm03-deductions-and-the-cost-price-ratio', 6, 'The Ekene CPR case ends in 2026 with 93000000.000000 still carried. What does the engine do with it, and under which provisions?', '["Deducts it in 2026 in full, since the last year of a field lifts the cap under para 2(2)(b)", "Moves it to companies income tax, where the cap does not apply", "Reports it as forfeited at cessation, non-deductible under para 2(2)(c) and s.264(q)", "Carries it to a later field of the same company under s.272"]'::jsonb, 2, 'Para 2(2)(c) makes costs above the limit "upon the termination of upstream petroleum operations related to crude oil" non-deductible for the hydrocarbon tax, and s.264(q) lists them among items never deducted. The engine reports cpr_forfeited_at_cessation, equal to the last year''s carry. No provision lifts the cap in the last year. Companies income tax already deducted the opex in full as it was spent, so nothing moves across. Consolidation under s.272 is concept-only and the engine does not compute it.'),
  ('pia', 'intermediate', 'module', 'm03-deductions-and-the-cost-price-ratio', 7, 'Sixth Schedule para 2(2)(a) allows a carried cost in later years "provided that the total costs to be deducted shall not exceed the actual costs incurred". What does that limit mean on a ledger?', '["A carried cost may be claimed only in the next year", "The carry may not exceed 65 percent of the year''s costs", "The cap lifts in any year whose costs fall", "Each cost is deducted once"]'::jsonb, 3, 'The words cap the total over the life: a cost carried forward is claimed once and never inflated or repeated. Nothing in para 2(2)(a) restricts the carry to the next year; a carried cost waits for any later year with room. The 65 percent figure is the per-year limit of para 2(2)(b), measured on revenue. No provision lifts the cap.'),
  ('pia', 'intermediate', 'module', 'm03-deductions-and-the-cost-price-ratio', 8, 'Para 2(2)(b) says a carried cost claimed later "shall be such an amount that if added to the sum of the total costs to be allowed as deduction under subparagraph (1) shall not exceed the specified cost price ratio limit of 65% ;". What does that rule do?', '["It gives the carried amount a second 65 percent limit of its own each year", "It makes the carried amount and that year''s own costs share one 65 percent limit", "It lets a carried cost be claimed ahead of the year''s own costs whenever the limit is reached, with no cap on the year''s claim", "It restricts the carried amount to 65 percent of what was first carried out"]'::jsonb, 1, 'The text adds the carried amount to the year''s own costs and caps the sum at 65 percent of revenue, so one limit covers both. There is no second limit. The engine does claim the carried pool with this year''s opex before the capital allowance, but the whole claim still stops at the cap. Nothing scales the carried amount down by 65 percent.'),
  ('pia', 'intermediate', 'module', 'm03-deductions-and-the-cost-price-ratio', 9, 'Ekene Alpha claims 46563591.022444 against a cost price ratio cap of 147664400.000000 in 2026. What does the engine carry out of 2026?', '["Nothing, because the whole pool fits under the cap", "Whatever room is left between cap and claim", "Its 2026 capital allowance", "The gas share of opex"]'::jsonb, 0, 'The engine claims the lesser of the pool and the cap; Alpha''s pool is well below its cap, so all of it is claimed and nothing is carried. The difference between cap and claim is unused room and carries nothing forward. The capital allowance is carried only when the cap binds. The gas share of shared costs stays on the gas side of the tax and is never carried in the hydrocarbon tax pool.'),
  ('pia', 'intermediate', 'module', 'm03-deductions-and-the-cost-price-ratio', 10, 'A lease''s recoverable pool in a year is exactly equal to that year''s cost price ratio cap. What does the engine claim and carry?', '["Only 65 percent of the pool, with the rest carried, as the cap is 65 percent", "The pool less one unit, with that unit carried, as the cap is a strict limit", "Nothing at all, because a pool at the limit sends the whole year to the carry", "It claims the whole pool and carries nothing"]'::jsonb, 3, 'The engine claims the lesser of the recoverable pool and the cap, so a pool equal to the cap is claimed in full and carries nothing. The 65 percent applies to revenue to set the cap; it is never applied to the pool. The limit reads "shall not exceed", which a pool equal to it meets. Nothing sends a year''s whole pool to the carry.'),
  ('pia', 'intermediate', 'module', 'm03-deductions-and-the-cost-price-ratio', 11, 'The worked example states a preceding year''s opex of 170000000 USD. What HCDT does the engine deduct in 2025, and under which provisions?', '["15000000.000000, the stated NDDC sum, which the case enters in the HCDT line", "5100000.000000, 3 percent of that opex, under s.240(2) and s.263(1)(h)", "3 percent of the 2025 opex itself, since s.240(2) reads the current year", "Nothing, since HCDT is paid from profit after tax and s.264(l) bars it"]'::jsonb, 1, 'Section 240(2) sets the contribution at 3 percent of the actual operating expenditure of the preceding financial year, so 3 percent of 170000000 USD is 5100000.000000, and s.263(1)(h) makes it deductible. 15000000.000000 is the fixed NDDC sum on its own line. The contribution reads the preceding year, which is why the case states it. Section 264(l) bars income and profits taxes; the trust contribution is deductible under s.257(1).'),
  ('pia', 'intermediate', 'module', 'm03-deductions-and-the-cost-price-ratio', 12, 'Ekene Alpha''s HCDT is 0.000000 in 2026 and 720000.000000 in 2027. Why is 2026 zero?', '["HCDT waits for a field''s first full producing year", "The 2026 capex of 120000000 USD absorbs the contribution inside the cost price ratio", "No preceding year''s opex was stated for the first ledger year", "Alpha is a converted lease, and converted leases pay HCDT from the second year"]'::jsonb, 2, 'HCDT is 3 percent of the preceding year''s opex; the first ledger year reads the stated pia_prior_year_opex_usd, which is 0 when not stated, and 2027 reads 2026 opex of 24000000 USD, giving 720000.000000. No provision delays HCDT by production history or lease type; the engine simply had no prior-year figure. HCDT sits outside the cost price ratio and nothing absorbs it.'),
  ('pia', 'intermediate', 'module', 'm03-deductions-and-the-cost-price-ratio', 13, 'On the Ekene NDDC case, the 2026 NDDC levy is 450000.000000 on the opex base and 2250000.000000 on the total budget, and the hydrocarbon tax is 32109497.282609 against 31569497.282609. Why is the tax lower on the total budget base?', '["The larger levy is deducted in the hydrocarbon tax base, which lowers the profit taxed", "Its capex enters the cost price ratio a second time on that base", "A credit against the tax itself, equal to the larger levy", "The total budget base switches the lease to the 15 percent class"]'::jsonb, 0, 'The NDDC levy is deductible for the hydrocarbon tax under s.263(1)(h) (at the liquids share), so a larger levy lowers the chargeable profit and the tax. The capex enters the levy base only; the levy sits outside the cap and adds nothing to it. A levy is a deduction in the base and gives no credit against the tax. The levy base has no effect on the s.267 class. In 2027, with no capex, both bases give 450000.000000.'),
  ('pia', 'intermediate', 'module', 'm03-deductions-and-the-cost-price-ratio', 14, 'The engine charges the NDDC levy as 3 percent of the total annual budget, taken as opex plus capex. What source does that figure rest on?', '["PIA s.263(1)(h), which sets the levy at 3 percent of the total annual budget of every company", "The Petroleum Royalty Regulations 2022, which set the NDDC levy beside the royalty rates", "PIA s.240(2), the same 3 percent that sets the host communities trust contribution", "A secondary source, said so where it is used"]'::jsonb, 3, 'The course names the Niger-Delta Development Commission (Establishment, etc.) Act 2000 s.14(2)(b), as amended 2017, and that Act was not read: the 3 percent of the total annual budget comes from published commentary, a secondary source, and is stated as such. PIA s.263(1)(h) makes the contribution deductible and sets no rate. The Regulations set royalties only. Section 240(2) sets the HCDT on the preceding year''s opex, which is a different instrument.'),
  ('pia', 'intermediate', 'module', 'm03-deductions-and-the-cost-price-ratio', 15, 'Which of these may the hydrocarbon tax base never deduct, under PIA s.264?', '["Levies, stamp duties and fees owed to any government", "Companies income tax and the tertiary education tax", "The host communities development trust contribution", "A contribution to an approved decommissioning fund"]'::jsonb, 1, 'Section 264(l) bars the tertiary education tax, companies income tax and any other income or profits tax, charged in Nigeria or elsewhere, from the hydrocarbon tax base. Levies, stamp duties and fees are deductible under s.263(1)(f), the trust contribution under s.263(1)(h), and an approved decommissioning fund contribution under s.263(1)(e).'),
  ('pia', 'intermediate', 'module', 'm04-allowances', 1, 'A capital spend''s whole five-year life falls in years under the Act alone. What fraction of it does the engine claim in year of life 4, the fifth year?', '["0.200000, the same share as each of the four years before", "0.000000, since the fifth year holds only the retained share", "0.190000 plus the retained 1 percent, released that year", "0.190000, the fifth-year rate"]'::jsonb, 3, 'PIA Fifth Schedule para 17(1) prints "20% 20% 20% 20% 19%", and the engine returns 0.190000 for year of life 4 in a year under the Act alone. 0.200000 in the fifth year is the Nigeria Tax Act 2025 schedule. Year of life 5 is the one that claims 0.000000. The retained 1 percent is never released in the ledger, because para 5(2) holds it until disposal and the ledger has no disposal event.'),
  ('pia', 'intermediate', 'module', 'm04-allowances', 2, 'Under the Act alone the capital allowance schedule claims 20, 20, 20, 20 and 19 percent of a spend. What happens to the last 1 percent of its cost in the engine''s ledger?', '["Claimed in year of life 5, the year after the 19 percent, once the schedule has run", "It is retained in the books until disposal and never claimed in the ledger, since the ledger has no disposal event", "It moves into the carried cost pool and waits there for a later year with room enough under the cap to claim it in full", "Added to the fifth year''s production allowance, so the barrels of that year carry it"]'::jsonb, 1, 'Para 5(2) says "there shall be retained in the books, in respect of each asset 1% of the initial cost of the asset which may only be written off in accordance with subparagraph (3)", on disposal. The engine has no disposal event, so it never claims it; year of life 5 claims 0.000000. The carried pool holds costs the cap turned away, and holds no unclaimed schedule share. The production allowance is a sum per barrel with no cost behind it.'),
  ('pia', 'intermediate', 'module', 'm04-allowances', 3, 'A learner sets pia_capex_recovery_years to 4. How does the engine respond?', '["It refuses, since the texts fix the capital allowance at five years", "A run at 25 percent a year over four years, named in a note", "The five-year schedule runs and the stated life is ignored", "It rounds the life to one the texts allow, with a note"]'::jsonb, 0, 'The engine''s own words open: "pia_capex_recovery_years is 4, but the PIA Fifth Schedule para 17(1) and NTA First Schedule Part II para 14(1) fix the capital allowance at five years (20, 20, 20, 20, 19 percent under the PIA; 20 percent a year under the NTA)." Any stated life other than 5 is refused, and a refusal returns no ledger. The engine never overrides a stated input silently and never rounds it; the fix is to leave it unset or set 5.'),
  ('pia', 'intermediate', 'module', 'm04-allowances', 4, 'On a lease where the cost price ratio cap binds, which of this year''s costs does the engine carry forward first?', '["Opex for the year, which the engine claims after the capital allowance", "The HCDT contribution, which enters the pool at the liquids share", "This year''s capital allowance", "The production allowance, as the last deduction in the base"]'::jsonb, 2, 'The engine claims the carried pool and this year''s opex first and this year''s capital allowance last, so when the cap binds the capital allowance is the first cost left over. Opex is claimed before the capital allowance. HCDT sits outside the cap and is never carried. The production allowance is deducted outside the cap, from assessable to chargeable profit, and is never part of the pool.'),
  ('pia', 'intermediate', 'module', 'm04-allowances', 5, 'Oil sells at 75 USD/bbl. How much production allowance does a converted lease earn on 1000000 barrels?', '["8000000.000000, the first tier", "4000000.000000, the second tier", "2500000.000000, the 2.50 USD leg", "20 percent of the price on every barrel"]'::jsonb, 2, 'PIA Sixth Schedule para 1(1) gives converted leases "the lower of US $2.50 per barrel and 20% of the fiscal oil price"; at 75 USD/bbl the fixed leg is lower, so the allowance is 2.50 USD on each barrel, 2500000.000000. The 8.00 and 4.00 USD tiers belong to leases granted out of new acreage. Twenty percent of 75 USD is far above 2.50, so the price leg does not apply.'),
  ('pia', 'intermediate', 'module', 'm04-allowances', 6, 'A converted lease produces 1000000 barrels at one cent below 12.50 USD/bbl. What allowance does the engine return, and which leg applies?', '["2498000.000000, the 20 percent price leg", "2500000.000000, since the 2.50 USD leg holds at every price", "2000000.000000, as prices under 12.50 fall to a fixed floor", "0.000000: no allowance below it"]'::jsonb, 0, 'At 12.50 USD/bbl the two legs are equal (20 percent of 12.50 is 2.50), and below it the price leg is the lower one, so one cent below returns 2498000.000000. The 2.50 USD leg applies only where it is the lower of the two. 2000000.000000 is the return at 10 USD/bbl, where 20 percent of the price is lower still; there is no fixed floor. The allowance never switches off at the crossing.'),
  ('pia', 'intermediate', 'module', 'm04-allowances', 7, 'A lease granted out of new acreage onshore produces 1000000 barrels at 30 USD/bbl with nothing produced before. What production allowance does the engine return?', '["8000000.000000, the fixed first-tier leg", "2500000.000000, the converted-lease leg", "4000000.000000, the tier after the cap", "6000000.000000"]'::jsonb, 3, 'Para 1(2)(a) gives the lower of 8.00 USD and 20 percent of the price below the cap. At 30 USD/bbl, 20 percent of the price is below 8.00 USD, so the allowance is 6000000.000000. 8000000.000000 is the return at 75 USD/bbl. The converted-lease allowance applies to converted leases, and this is a new lease. The 4.00 USD tier starts only after 50 million barrels, and a low price does not move a barrel across the cap.'),
  ('pia', 'intermediate', 'module', 'm04-allowances', 8, 'Suppose 49500000 barrels came out of a new onshore field before this year, and this year adds 1000000 at 75 USD/bbl. What allowance results?', '["8000000.000000, since the year started below the cap and the whole year stays in the first tier", "6000000.000000, with 500000 barrels below the cap and 500000 after it", "4000000.000000, every barrel of the year on the 4.00 USD tier", "2500000.000000, the converted-lease leg, once the history passes 49 million barrels"]'::jsonb, 1, 'A year that crosses the cap is split at the cap: 500000 barrels at 8.00 USD and 500000 at 4.00 USD, 6000000.000000 in all, with below and after the cap printed as 500000 each. Keeping the whole year in the first tier or moving the whole year to the second both ignore the split the engine makes. 2500000.000000 is the converted-lease allowance, and a new lease keeps its own tiers whatever its history.'),
  ('pia', 'intermediate', 'module', 'm04-allowances', 9, 'The Ekene new onshore lease had produced 49000000 barrels before 2026 and produces 3000000 barrels in 2026 at 75 USD/bbl. How does the engine reach its 2026 allowance of 16000000.000000?', '["3000000 barrels at a blended rate, with the cap spread over the whole year", "2000000 barrels below the cap at 8.00 USD and 1000000 after it earning nothing", "1000000 barrels below the cap at 8.00 USD and 2000000 after it at 4.00 USD", "Every barrel at 8.00 USD, less a 50 million barrel cap deduction"]'::jsonb, 2, 'One million barrels remain below the 50 million barrel onshore cap, and they earn 8.00 USD each; the other two million are past it and earn 4.00 USD each, 16000000.000000 in all. The engine splits the year at the cap and blends nothing. The second tier pays the lower of 4.00 USD and 20 percent of the price, which is 4.00 USD at 75, so no barrel earns zero. There is no cap deduction; the cap is a volume limit.'),
  ('pia', 'intermediate', 'module', 'm04-allowances', 10, 'In 2027 the same lease produces 2500000 barrels at 75 USD/bbl. What allowance does the engine return?', '["Every barrel at 8.00 USD, since each year''s tier restarts on 1 January", "0.000000, since a lease past its cap gets no production allowance for the rest of its life", "The converted-lease allowance", "10000000.000000, every barrel at 4.00 USD"]'::jsonb, 3, 'The cap counts cumulative production from the start, and the lease crossed it in 2026, so every 2027 barrel earns the second tier: 4.00 USD, the lower leg at 75 USD/bbl, giving 10000000.000000. The tier does not restart each year. Para 1(2)(a) keeps "the lower of US $4.00 per barrel and 20% of the fiscal oil price thereafter", so the allowance continues. A new lease stays a new lease past its cap.'),
  ('pia', 'intermediate', 'module', 'm04-allowances', 11, 'On 1000000 new onshore barrels at 75 USD/bbl, a year that ends exactly on the cap returns 8000000.000000, and one barrel further returns 7999996.000000. What does that show?', '["The engine rounds any year within one barrel of the cap back into the first tier", "The barrel landing on the cap earns the first tier, and the one past it earns 4.00 USD", "The cap is inclusive only in years under the Act alone", "Every barrel of the year drops a few cents once the cap is crossed"]'::jsonb, 1, 'A year that ends exactly on the cap has no barrel after it, so all of it earns 8.00 USD; one barrel further, that last barrel earns 4.00 USD, which is 4 less, giving 7999996.000000. The engine applies an exact split and no rounding. The rule is stated per rule for the cap and does not depend on the framework of the year. Only the barrel past the cap changes tier.'),
  ('pia', 'intermediate', 'module', 'm04-allowances', 12, 'A new onshore lease, its new-lease rate stated, has produced for years, and a learner leaves pia_prior_cumulative_oil_bbl at 0. What does the engine do?', '["It treats the lease as fresh, paying the first tier until the ledger itself reaches the cap", "It refuses the run, since a new lease must state its production history before any year is taxed", "It reads the field''s history from the production rows, counting back from the first ledger year", "It applies the 4.00 USD second tier to every barrel"]'::jsonb, 0, 'The cap counts from the start of production, and the engine learns where a field stands only from the stated pia_prior_cumulative_oil_bbl, adding each ledger year''s crude oil and condensate to it. With 0 the lease looks fresh and earns 8.00 USD a barrel until the ledger''s own barrels reach the cap, which can overstate the allowance. The engine does not refuse a 0, has no production history beyond the rows it is given, and never guesses the second tier.'),
  ('pia', 'intermediate', 'module', 'm04-allowances', 13, 'Every PIA run prints: "The realised oil and condensate prices stand in for the Commission''s fiscal prices (PIA Seventh Schedule para 8), so the additional tax at the fiscal price (PIA s.268; NTA s.73) is not computed." What does that mean for the production allowance''s 20 percent leg?', '["A fiscal price the learner must type", "It is switched off, lacking the fiscal price", "Twenty percent of the price benchmark", "It reads the realised price"]'::jsonb, 3, 'The text says "20% of the fiscal oil price"; the engine uses the realised price and states that choice in its note, which is part of the result. There is no fiscal price input and no refusal. The leg stays on: at 10 USD/bbl a converted lease earns 2000000.000000 through it. Royalty by price benchmarks belong to the royalty and never enter the allowance.'),
  ('pia', 'intermediate', 'module', 'm04-allowances', 14, 'The Ekene new onshore lease''s allowance falls from 16000000.000000 to 10000000.000000 as it passes the cap. Which lines does crossing the cap move?', '["The chargeable profit and the hydrocarbon tax", "The cost price ratio claim, since the allowance is claimed inside the 65 percent cap", "Companies income tax as well", "The assessable profit"]'::jsonb, 0, 'The production allowance is deducted from assessable profit to reach chargeable profit, outside the cap, so the cap on volume moves the chargeable profit and through it the tax. The cost price ratio lines sit above that step and do not read the allowance. Companies income tax has no production allowance in its base. The assessable profit is computed before the allowance comes off.'),
  ('pia', 'intermediate', 'module', 'm04-allowances', 15, 'The Ekene deep offshore lease is a new lease producing 21900000 barrels at 75 USD/bbl in 2025, a year under the Act alone. What production allowance does the engine return?', '["0.000000, since deep offshore pays no hydrocarbon tax in 2025 and so earns no allowance on any barrel", "175200000.000000, 8.00 USD on every barrel", "The 2.50 USD leg on every barrel", "The 4.00 USD tier on every barrel"]'::jsonb, 1, 'Para 1(2)(c) gives deep offshore and frontier new leases the lower of 8.00 USD and 20 percent of the price up to 500 million barrels, and at 75 USD/bbl that is 8.00 USD a barrel, 175200000.000000. The engine computes the base and the allowance even where s.260(3) sets the tax at zero. The 2.50 USD leg is for converted leases. The 4.00 USD tier starts only past the cap.'),
  ('pia', 'intermediate', 'module', 'm05-income-tax-alongside', 1, 'The Ekene new onshore lease is run with its stated new-lease rate changed from 15 to 30. What is companies income tax in 2026 under each run?', '["50223464.673913 under both stated readings", "Lower under the stated 30, since the larger hydrocarbon tax is deducted", "Higher under the stated 30", "Refused under the stated 30 until companies income tax states its own rate"]'::jsonb, 0, 'PIA s.302(5) makes the hydrocarbon tax non-deductible in determining companies income tax. So a stated rate that doubles the hydrocarbon tax (22711732.336957 to 45423464.673913) leaves companies income tax at 50223464.673913 in both runs. If the tax were deductible the higher reading would lower it; nothing adds the hydrocarbon tax to it either. Companies income tax runs at 30 percent unless stated and needs no reading.'),
  ('pia', 'intermediate', 'module', 'm05-income-tax-alongside', 2, 'Which stream of revenue does companies income tax charge that the hydrocarbon tax leaves out?', '["Condensate, as a natural gas liquid", "Crude oil sold below the fiscal price", "Gas", "Barrels under the production allowance"]'::jsonb, 2, 'Companies income tax is charged on oil and gas together; the hydrocarbon tax charges crude oil and condensate only, so gas revenue is in one base and out of the other. Condensate is inside the hydrocarbon tax by s.260(1)(a). The fiscal price is concept-only and removes no crude oil from the tax. The production allowance is a deduction per barrel and takes no revenue out of the base.'),
  ('pia', 'intermediate', 'module', 'm05-income-tax-alongside', 3, 'The Ekene gas field''s 2026 companies income tax is 10713000.000000 on an assessable profit of 47710000.000000. Why is the tax below 30 percent of that assessable profit?', '["The hydrocarbon tax is deducted first", "Its own capital allowance comes off the assessable profit before the 30 percent applies", "Gas used in-country is taxed at a lower companies income tax rate than gas sold for export", "The cost price ratio holds back part of the opex"]'::jsonb, 1, 'The engine''s companies income tax base is gross revenue from oil and gas less every royalty, opex in full, HCDT and the NDDC levy, and then less its own capital allowance; the assessable profit it prints is the figure before that allowance, and the 30 percent applies after it. The hydrocarbon tax is never deducted (s.302(5)), and on this field it is 0.000000 anyway. The in-country share lowers the gas royalty rate and leaves the tax rate at 30 percent. The cost price ratio does not apply to companies income tax, which deducts opex in full.'),
  ('pia', 'intermediate', 'module', 'm05-income-tax-alongside', 4, 'On the Ekene CPR case in 2026 the hydrocarbon tax chargeable profit is 8792934.782609 while the companies income tax assessable profit is -457065.217391. Why do the two bases point in opposite directions?', '["Its deduction of the hydrocarbon tax pushes the income tax base below zero", "The hydrocarbon tax adds back the NDDC levy that companies income tax deducts", "A later year''s revenue is what companies income tax reads", "Companies income tax deducts the full opex, while the 65 percent cap holds back the hydrocarbon tax claim"]'::jsonb, 3, 'The cap limits the hydrocarbon tax claim to 29250000.000000 in 2026 and carries the rest, so its base stays positive; companies income tax deducts the 40000000 USD of opex in full and has no cap, so its base goes below zero. Companies income tax does not deduct the hydrocarbon tax. The NDDC levy is deducted in both bases. Both taxes read the same year''s revenue.'),
  ('pia', 'intermediate', 'module', 'm05-income-tax-alongside', 5, 'PIA s.302(11)(a) lets companies income tax deduct "all rents and royalties the liability for which was incurred by the company during that period in respect of crude oil sold, condensate sold and natural gas sold or delivered or disposed of in any other commercial manner". Which royalty does that add beyond the hydrocarbon tax base?', '["The royalty by price", "The liquids production royalty", "Non-associated condensate royalty", "The gas royalty"]'::jsonb, 3, 'The hydrocarbon tax base deducts the liquids production royalty and the royalty by price under s.263(1)(b), and leaves the gas royalty out because gas is outside the tax. Companies income tax deducts every royalty, the gas royalty included. Both liquids royalties are already deducted in the hydrocarbon tax base, outside the cap. Non-associated gas condensate is outside the hydrocarbon tax under s.260(1)(b)(ii) and has no rate.'),
  ('pia', 'intermediate', 'module', 'm05-income-tax-alongside', 6, 'On the Ekene CPR case, 2024 is a year under the Act alone with a companies income tax assessable profit of 23999396.909159, and the engine claims a capital allowance of 15999597.939440. What limits the claim?', '["The 65 percent cost price ratio of the Sixth Schedule, applied to companies income tax in the same way as to the hydrocarbon tax", "Two thirds of the assessable profit, the restriction of CITA para 24(7) as substituted by Finance Act 2023 s.9(b)", "The 19 percent fifth-year rate of the Fifth Schedule", "A 30 percent cap on the allowance under NTA s.56(b), the companies income tax rate itself"]'::jsonb, 1, 'In a year under the Act alone the capital allowance claimed against companies income tax is limited to two thirds of the assessable profit, with the excess carried forward; two thirds of 23999396.909159 is the 15999597.939440 claimed. The cost price ratio limits the hydrocarbon tax only. The schedule rate sets the allowance itself, and 2024 is the spend''s first year. The 30 percent in s.56(b) is the tax rate and caps no allowance.'),
  ('pia', 'intermediate', 'module', 'm05-income-tax-alongside', 7, 'On the Ekene onshore lease, cit_allowance_restricted reads true in 2024 and 2025, yet the whole 18000000.000000 allowance is claimed in both years. What does the flag mean?', '["The rule is in force that year", "The allowance was cut by a third", "The claim moved to 2026", "The company is in gas operations and is exempt, which the engine marks as a restricted year"]'::jsonb, 0, 'The flag marks the two thirds rule as in force in a year under the Act alone, whether or not it bites. On this lease two thirds of each assessable profit (153422584.102902 and 138422805.570953) is far larger than 18000000.000000, so the whole allowance is claimed and nothing is carried. Nothing was cut or carried. A company in gas operations is exempt, and its flag would read false.'),
  ('pia', 'intermediate', 'module', 'm05-income-tax-alongside', 8, 'Who is exempt from the two thirds restriction on the companies income tax capital allowance, and how does a learner tell the engine?', '["Any 15 percent hydrocarbon tax payer, set with the licence type PPL", "A lease in deep offshore, set with its terrain", "A company in upstream or midstream gas operations, set with pia_cit_company_gas_operations true", "Any company with a loss carried forward"]'::jsonb, 2, 'The engine''s note says: "Companies in upstream or midstream gas operations are exempt: set pia_cit_company_gas_operations to true." The licence type moves the hydrocarbon tax class and has no effect on companies income tax. Terrain is no exemption from this rule. A carried loss is a separate pool and grants no exemption.'),
  ('pia', 'intermediate', 'module', 'm05-income-tax-alongside', 9, 'The engine''s note on the two thirds restriction says: "The wording in force before 1 May 2023 was not read; the engine applies the same restriction to every year before 2026." How does the engine treat a 2022 ledger year?', '["No restriction at all, since the Finance Act 2023 took effect on 1 May 2023 and nothing earlier binds", "It applies the same two thirds restriction and states that choice in its note", "It refuses the year until the wording in force before 1 May 2023 is supplied", "A one-half restriction, the older rule"]'::jsonb, 1, 'The restriction comes from CITA Second Schedule para 24(7) as substituted by Finance Act 2023 s.9(b), effective 1 May 2023. The engine did not read the earlier wording, so it applies the same restriction to every year before 2026 and says so in kpis.pia_notes, which is part of the result. It does not refuse such a year, and no one-half rule appears in any text the course read.'),
  ('pia', 'intermediate', 'module', 'm05-income-tax-alongside', 10, 'The companies income tax chargeable profit of the CPR case is -65495752.569896 in 2026. Where does that loss go?', '["Set against the hydrocarbon tax chargeable profit of the same year", "It joins the cost price ratio pool of the hydrocarbon tax and is forfeited with that pool at cessation", "It is carried to the next year as 65495752.569896 and reduces nothing in the hydrocarbon tax", "Written off at the year end"]'::jsonb, 2, 'The engine keeps a hydrocarbon tax loss and a companies income tax loss apart, and a loss in one never reduces the other, so the 2026 loss is carried as 65495752.569896 for a later companies income tax profit. The cost price ratio carry is a different thing, inside the hydrocarbon tax, and the loss never joins it. A loss is carried to the next year and used there; it is not written off.'),
  ('pia', 'intermediate', 'module', 'm05-income-tax-alongside', 11, 'PIA s.265(3) says a loss deduction "shall be made so far as possible from the amount, if any, of the adjusted profit of the first accounting period after that in which the loss was incurred,". Where does the engine use a loss first?', '["Same year, against the other class", "Spread over the next five years", "The ledger''s last year", "In the next year"]'::jsonb, 3, 'The engine carries a loss to the next year and uses it there, as far as that year''s profit allows, which is what s.265(3) says; the Nigeria Tax Act 2025 restates it at s.70(3). The two classes of rate are kept separate under s.265(2), and the hydrocarbon tax and companies income tax pools are kept apart. No text spreads a loss over five years, and the last year of the ledger is where a cost price ratio carry is forfeited, a different rule.'),
  ('pia', 'intermediate', 'module', 'm05-income-tax-alongside', 12, 'PIA s.265(4) lets a company "elect in writing that a deduction or any part to be made under this section shall be deferred to and be made in the succeeding accounting period". How does the engine handle that election?', '["It takes no such election, so the provision is concept-only and never graded on a number", "A stated deferral input moves the loss, in whole or in part, to the next year", "Every loss is deferred by one year automatically, as the election is the default", "It refuses a ledger with a loss until the election is stated in the terms"]'::jsonb, 0, 'The engine uses a loss in the next year as far as possible and has no input for an election to defer; the election is taught from its text as a concept-only provision. There is no deferral switch, the engine does not defer any loss on its own, and a loss is a normal result that the engine returns.'),
  ('pia', 'intermediate', 'module', 'm05-income-tax-alongside', 13, 'Section 260(3) keeps deep offshore outside the hydrocarbon tax. On the 60,000 bopd deep offshore case in 2025, a year under the Act alone, what companies income tax is due?', '["0.000000", "795646660.199557, the whole chargeable profit", "30 percent of the production allowance", "291253998.059867"]'::jsonb, 3, 'Section 260(3) takes deep offshore out of the hydrocarbon tax Part only, so the tax is not zero; companies income tax is charged on the whole profit, 291253998.059867 in 2025. 795646660.199557 is the hydrocarbon tax chargeable profit, a base and never a tax. The production allowance is a deduction in the hydrocarbon tax base and is not taxed.'),
  ('pia', 'intermediate', 'module', 'm05-income-tax-alongside', 14, 'Which deduction in the hydrocarbon tax base has no counterpart in the companies income tax base?', '["The capital allowance", "The Sixth Schedule''s per-barrel allowance", "The HCDT contribution, which s.257(1) allows for the hydrocarbon tax alone", "The royalty by price, which companies income tax adds back as a charge on price"]'::jsonb, 1, 'The Sixth Schedule production allowance belongs to the hydrocarbon tax alone, and companies income tax has none. Companies income tax has its own capital allowance claim. Section 257(1) makes the HCDT contribution deductible for the hydrocarbon tax and for companies income tax, so both bases take it. Every royalty, the royalty by price included, is deducted for companies income tax under s.302(11)(a).'),
  ('pia', 'intermediate', 'module', 'm05-income-tax-alongside', 15, 'At what rate does the engine charge companies income tax on an oil and gas company, unless a rate is stated?', '["The lease''s hydrocarbon tax rate", "20 percent, as for allowances", "30 percent", "0 percent, the small company rate"]'::jsonb, 2, 'Companies income tax runs at 30 percent unless stated; NTA s.56(b) charges "any other company, at the rate of 30 per cent from the commence- ment of this Act." The hydrocarbon tax class does not reach companies income tax: the Ekene new onshore lease pays the same companies income tax under both stated readings. Twenty percent is the yearly capital allowance fraction and no tax rate. The 0 percent rate is for a small company, which an oil and gas producer on these cases is not.'),
  ('pia', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'Reading one year of hydrocarbon tax, the course puts four questions before the rate: the scope, the royalty rate, the cap, and the allowances. Why does the rate come last?', '["Only the rate can move under a stated reading, so the course keys it from the reading it prefers", "The rate acts on a chargeable profit the other four steps have already settled", "Its value is read from the cap, which must be known first", "It is the first line the engine computes"]'::jsonb, 1, 'The base (scope, royalty, cap, allowances) sets the chargeable profit and the s.267 rate is applied to it, so once the base is traced the tax is the rate on it. A stated reading can move the rate on a new-acreage lease, and the course keys neither reading. The cost price ratio reads revenue and costs; it has nothing to do with the rate. The engine applies the rate at the end of the base and at no earlier point.'),
  ('pia', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'On the worked example inputs the hydrocarbon tax assessable profit is 1,058,241,648.189209 and the chargeable profit 952616648.189209. What comes off between the two?', '["The royalties and HCDT, which the Act deducts only at the chargeable step", "Companies income tax", "The NDDC levy and the carried cost, deducted once the cap is known", "The capital allowance and the production allowance"]'::jsonb, 3, 'The step from assessable to chargeable profit deducts the capital allowance the cap let through (60000000.000000) and the production allowance (45625000.000000). Royalties, HCDT and the NDDC levy come off before the assessable profit. Section 264(l) bars companies income tax from the hydrocarbon tax base at every step. There is no carried cost on this year, since the cap does not bind.'),
  ('pia', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'The worked example''s hydrocarbon tax is 285784994.456763 at a rate of 0.300000. Which provision puts that rate on the line?', '["PIA s.267(b), which names onshore and shallow water in its opening words", "A stated reading, since every shallow water lease rate is open", "PIA s.267(a), for a converted lease in shallow water", "Seventh Schedule para 10(2)(b)"]'::jsonb, 2, 'Section 267(a) gives 30 percent to petroleum mining leases selected under s.93(6)(b) and (7)(b), the converted producing areas, onshore and in shallow water; the worked example is a converted lease. Section 267(b) is the 15 percent class. The open reading covers leases granted out of new acreage, and this lease is converted, so nothing on the rate line is a stated reading. Para 10(2)(b) sets the 12.5 percent shallow water royalty.'),
  ('pia', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'On the worked example the cost price ratio cap is 949000000.000000 and the claim 242500000.000000. What does that mean for the carry and the forfeiture?', '["Nothing is carried to a later year and nothing can be forfeited when the ledger ends", "The unused room under the cap is carried forward to be claimed in a later year", "The difference between cap and claim is forfeited when the ledger ends", "A quarter of the cap is carried to the next year as a reserve"]'::jsonb, 0, 'The claim is far below the cap, so the whole pool is claimed; a carry exists only when the pool exceeds the cap, and forfeiture can only take cost that is still carried. Unused room under the cap is not a cost and is never carried or forfeited. No rule carries a share of the cap.'),
  ('pia', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'The worked example charges a royalty by price in 2025 at 80 USD/bbl. On which base does the engine charge it, and at what rate?', '["0.023910, on the Petroleum Royalty Regulations 2022 base, the engine default", "0.022464, on the Act''s own base year of 2020, which the engine applies as the law", "0.050000, the middle rate, charged at any price that falls between the two outer benchmarks", "0.000000, since royalty by price starts above 100 USD/bbl"]'::jsonb, 0, 'The base year is an open reading: the Petroleum Royalty Regulations 2022 (S.I. No. 73, Official Gazette No. 205, Vol. 109, 22 November 2022) start the benchmarks in 2021 and the Act in 2020. The engine follows the Regulations unless told otherwise and says so in its note; at 80 USD/bbl in 2025 that returns 0.023910. The Act base gives 0.022464 at the same price, and the course grades neither reading against the other. 5 percent is the rate at the middle benchmark only, and the rate is 0 only at or below the low benchmark (54.120000 in 2025 on the Regulations base).'),
  ('pia', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'The worked example states the NDDC levy as a fixed sum of 15000000 USD. What does the engine do with the 3 percent of the total annual budget?', '["Adds the percentage on top of the fixed sum", "Whichever of the two is larger is charged", "The fixed sum replaces the percentage", "It refuses the case, since the NDDC Act 2000 sets 3 percent and a fixed sum overrides a statutory rate"]'::jsonb, 2, 'When pia_nddc_levy_fixed_usd is given, the fixed sum replaces the percentage, so the 2025 NDDC line is 15000000.000000. The engine never adds the two or takes the larger. The 3 percent of total budget rests on a secondary source, and the fixed sum is a stated alternative the engine accepts.'),
  ('pia', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'Companies income tax on the worked example year is 299472494.456763. Which statement about it is right?', '["Thirty percent of the hydrocarbon tax chargeable profit, 952616648.189209, the same base the hydrocarbon tax uses", "A deduction of the hydrocarbon tax of 285784994.456763 comes first, before its 30 percent rate applies to what is left", "It is charged only on the revenue the cost price ratio let through", "It is computed on its own base, with the hydrocarbon tax kept out of it by s.302(5)"]'::jsonb, 3, 'Companies income tax reads its own base: every royalty, opex in full, HCDT, the NDDC levy and its own capital allowance, and s.302(5) keeps the hydrocarbon tax out of it. It is not a share of the hydrocarbon tax chargeable profit, which carries the production allowance companies income tax does not have. The cost price ratio does not apply to companies income tax.'),
  ('pia', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'Three carries appear in this tier. Which pairing of carry and rule is right?', '["A loss is capped each year by para 2(2)(b) and forfeited at cessation; the cost price ratio carry follows s.265", "The cost price ratio carry is capped each year by para 2(2)(b) and forfeited by para 2(2)(c); a loss sits in its own pool under s.265", "The two thirds carry is forfeited at cessation by para 2(2)(c)", "All three share one pool"]'::jsonb, 1, 'The cost price ratio carry holds cost the cap turned away, shares each later year''s 65 percent limit under para 2(2)(b), and is forfeited when crude oil operations end under para 2(2)(c): 93000000.000000 on the Ekene CPR case. A loss is a chargeable profit below zero, carried in its own pool for its own tax under s.265. The two thirds carry in companies income tax waits on its own limit, and forfeiture belongs to the cost price ratio alone. The engine keeps every pool apart.'),
  ('pia', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'On the Ekene new onshore lease the 2026 chargeable profit is 151411548.913043 under the stated 15 and under the stated 30. What does that show about the system?', '["The readings give the same tax, so the question is moot", "The chargeable profit is computed after the tax", "The reading reaches the base through the allowance", "The rate and the base are separate"]'::jsonb, 3, 'A licence type or a stated reading moves the rate; the royalty, the cap and the allowances move the base. So the chargeable profit is the same under both readings while the tax is 22711732.336957 at the stated 15 and 45423464.673913 at the stated 30. The readings do change the tax. The tax is computed after the chargeable profit. The production allowance depends on lease status and cumulative barrels, which the rate does not touch.'),
  ('pia', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'On Ekene Alpha in 2026 the total royalty is 18012822.226867. What is its production royalty on crude oil and condensate alone?', '["18012822.226867, the total royalty the engine prints", "13625099.038462", "4037323.188406, the royalty charged on price", "350400.000000, the gas royalty"]'::jsonb, 1, 'The total royalty is the liquids production royalty plus the gas royalty plus the royalty by price (on the Regulations base, the engine default). The part charged at the tranche rate on crude oil and condensate is the liquids production royalty, 13625099.038462. 4037323.188406 is the royalty by price and 350400.000000 the gas royalty; each has its own column. Name the part before reading a royalty.'),
  ('pia', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'Ekene Alpha is run at a 50 percent working interest. How does the engine treat the daily rate the royalty tranches read?', '["It reads the tranches at field level, then scales every money line to the share", "The barrels are halved first, so the daily rate, and with it the tranche rate, both fall below Alpha''s full-field figures", "Every tranche edge is halved to match the share", "It refuses a share below 100 percent"]'::jsonb, 0, 'Under the PIA regime every year runs at 100 percent field level, and then every money line is scaled to the working interest share, so the tranches, the caps and every rate are read at field level. Alpha''s total royalties are 79273732.707567 at 100 percent and 39636866.353784 at 50 percent. Halving barrels first would lower the rate, which the engine does not do. Nothing moves the edges, and a share below 100 percent is ordinary.'),
  ('pia', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'A hydrocarbon tax figure cannot be traced through the four questions of the Professional reading. Which inputs does the course say are the most likely cause?', '["The discount rate and the escalators", "The terrain and the licence type, which the engine reads from the water depth and the lease history", "The barrels produced before the ledger, or the preceding year''s opex", "The working interest, which changes the tranche rate"]'::jsonb, 2, 'The course names these two because each carries history the ledger cannot see: pia_prior_cumulative_oil_bbl places a new lease against its allowance cap, and pia_prior_year_opex_usd sets the first year''s HCDT. Discounting belongs to the cash flow course and never touches the hydrocarbon tax lines. The engine reads the terrain and licence as stated strings and never reads a water depth. The working interest scales money after the tranches are read at field level.'),
  ('pia', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'The worked example has crude oil only. Why does its run carry no note about shared costs?', '["The note appears only on a ledger with gas production in some year", "It was switched off by the stated NDDC sum", "A converted lease allocates costs by the Act", "It appears only in a year under the Act alone"]'::jsonb, 0, 'The sharedCosts note appears on a ledger with gas production in some year, because only then does the engine split opex, HCDT, NDDC and the capital allowance by the crude-plus-condensate share. With crude oil only, every shared cost belongs to the tax in full. The NDDC sum, the lease status and the framework of the year do not decide whether the note appears.'),
  ('pia', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'On a lease granted out of new acreage onshore, which of these can the course grade?', '["Hydrocarbon tax at the stated 15, the lower of the two readings and the one the text favours", "The tax line under the stated 30, the higher of the two readings and the safer choice", "An average of the two stated readings'' hydrocarbon tax, halfway between them", "Its chargeable profit, which the rate leaves alone"]'::jsonb, 3, 'The course never grades a figure the stated rate moves. On such a lease a graded figure is one the rate leaves alone: the chargeable profit, the allowances, the cost price ratio lines, companies income tax. Every option naming the hydrocarbon tax depends on the stated reading, whether 15, 30 or a blend, and the text does not favour either reading.'),
  ('pia', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'When reading a figure forfeited at cessation, which fact should be read beside it?', '["The first year''s HCDT", "The last year of the ledger", "The working interest, which decides whether the carry is forfeited at all or only scaled", "The stated new-lease rate"]'::jsonb, 1, 'The engine treats the last year of the ledger as the end of crude oil operations and forfeits the cost still carried then, so a ledger cut short forfeits the carry at the year it stops. HCDT sits outside the cap and plays no part. The working interest scales money after the arithmetic and never decides a forfeiture. The stated rate does not reach the cost price ratio.'),
  ('pia', 'intermediate', 'final', null, 1, 'A third of an onshore field''s 7500 bopd lies above 5,000 bopd. Which weighted rate applies to its liquids?', '["0.075000, the second tranche rate", "0.050000, below 10,000 bopd", "0.058333", "0.062500, the second tranche edge"]'::jsonb, 2, 'Two thirds of 7500 bopd sit in the first tranche at 5 percent and a third in the second at 7.5 percent, and the Regulations weight them over the whole volume, so the engine returns 0.058333. Charging 7.5 percent on every barrel ignores the first tranche. 5 percent holds only up to 5,000 bopd. 0.062500 belongs to exactly 10,000 bopd.'),
  ('pia', 'intermediate', 'final', null, 2, 'At 120000 bopd the engine returns 0.142708 onshore, 0.119792 in shallow water and 0.064583 in deep offshore. What do the three returns have in common?', '["Each stays below its terrain rate", "Each has reached its terrain rate of para 10(2), since every barrel past the small-field edge pays it", "All three use the onshore and shallow water tranches of 5,000 and 10,000 bopd before the terrain rate", "Each sits a fixed margin below its terrain rate"]'::jsonb, 0, 'A weighted rate keeps the low tiers on the first barrels, so even at 120000 bopd onshore stays below 15 percent, shallow water below 12.5 percent and deep offshore below 7.5 percent. The terrain rate falls only on the share above the edge. Deep offshore has one tier of 50,000 bopd and does not use the 5,000 and 10,000 bopd tranches. No fixed margin below the terrain rate appears anywhere in the scale.'),
  ('pia', 'intermediate', 'final', null, 3, 'Ekene Alpha''s liquids royalty rate is 0.059976 in 2026 and 0.057927 in 2027. Why does it fall?', '["The Regulations lower the second tranche rate by a set step each 1 January, so every later year of a ledger pays a little less on the same daily rate", "2027 has more calendar days than 2026", "Its royalty by price falls with the benchmarks", "Alpha declines, so its daily rate falls within the 5,000 to 10,000 bopd band and less of it pays 7.5 percent"]'::jsonb, 3, 'Alpha''s daily rate falls from 8320.000000 to 7321.600000 bopd, so a smaller share of the volume sits above 5,000 bopd at 7.5 percent and the weighted rate falls. The tranche rates are fixed in the text. Both years have 365 days. The royalty by price is a separate line with its own rate and does not enter the liquids royalty rate.'),
  ('pia', 'intermediate', 'final', null, 4, 'The rate function is handed a daily rate of -1. What does it return?', '["0.050000, the first tranche, applied to any daily rate at or below 5,000 bopd, negative rates included since they sit below the edge", "0.000000, since a field with no production pays no royalty", "A refusal: \"The crude oil and condensate daily rate must be a finite number of 0 or more; got -1.\"", "A result with a note that the daily rate was reset to 0"]'::jsonb, 2, 'The engine refuses a negative daily rate in its own words, stating the exact condition. A daily rate of 0 or more is accepted; below 0 there is no result, so no tranche rate and no zero rate come back. The engine never resets a stated input and attaches a note; a note belongs to a result, and a refusal returns none.'),
  ('pia', 'intermediate', 'final', null, 5, 'At 9999 bopd onshore the engine returns 0.062499, and at 10000 bopd 0.062500. What does the pair show about the scale?', '["The rate jumps at the edge from one band to the next, as a step scale would, so the two figures come from different formulas", "Below the edge the onshore terrain rate of 15 percent already applies to part of the volume, which is why 9999 bopd sits so close to the edge rate", "The engine rounds every daily rate up to 10,000 bopd", "The weighted rate climbs smoothly to the edge and meets the average of the two tranches exactly there"]'::jsonb, 3, 'Inside the second tranche the weighted rate rises barrel by barrel, reaching 6.250000 percent at 10,000 bopd, the average of 5 and 7.5 percent. There is no jump. The terrain rate enters only above 10,000 bopd. The engine does not round daily rates; 9999 is read as 9999.'),
  ('pia', 'intermediate', 'final', null, 6, 'The Nigeria Tax Act 2025 (Official Gazette No. 117, Vol. 112, 26 June 2025) restates the tranches in its Seventh Schedule para 6(2)(d)(ii), printing "5,000 bop". How does the course treat that?', '["It quotes the misprint as printed and says so", "It corrects the text to bopd inside the quotation marks so the quotation reads cleanly", "It reads bop as barrels a month and applies a monthly tranche", "It drops the NTA quotation and cites the Regulations in its place"]'::jsonb, 0, 'A misprint in a text is quoted as printed and said to be one: the rest of that paragraph and the Act write bopd. Changing a quotation would make it inexact, and the quotations are checked character by character. Nothing in the course reads bop as a different unit. The NTA wording is quoted beside the Act''s, so nothing is dropped.'),
  ('pia', 'intermediate', 'final', null, 7, 'Regulations r.14(6) weights a field lying partly in shallow water and partly in deep offshore. At 60000 bopd the engine returns 0.114583 as shallow water and 0.054167 as deep offshore. What are these two figures?', '["The weighted rate of the straddling field, which the engine computes from both", "Two readings of an open question, of which the course grades neither", "The two limbs of the method, each as if the whole field sat in one terrain", "The rates the field pays before and after 1 January 2026"]'::jsonb, 2, 'Rule 14(6) opens: "(a) determine the royalty rate as if the entire field is in shallow water ;", and the same for deep offshore, then weights the two by each terrain''s share of production. The engine gives each limb from a stated terrain and has no share-of-production input, so the weighted rate is never computed and the provision is concept-only. The terrain rates are not one of the three open readings, and the tranches read no framework.'),
  ('pia', 'intermediate', 'final', null, 8, 'Under the Nigeria Tax Act 2025 (Official Gazette No. 117, Vol. 112, 26 June 2025), what does s.65(2)(a) do to the scope of the hydrocarbon tax?', '["It widens the scope to natural gas sold for export, taxing it beside crude oil", "It keeps the scope of PIA s.260(1)(a) in the same words", "It narrows the scope to crude oil and drops condensate from the tax altogether", "It moves the scope to the Seventh Schedule"]'::jsonb, 1, 'The NTA re-enacts the Act''s hydrocarbon tax Part, and its s.65(2)(a) repeats the words of PIA s.260(1)(a) as the course prints them side by side. Nothing is widened to export gas or narrowed to crude oil alone. The scope sits in the NTA''s hydrocarbon tax Part; its Seventh Schedule deals with royalty.'),
  ('pia', 'intermediate', 'final', null, 9, 'The Ekene frontier case at 120 USD/bbl in 2026 pays hydrocarbon tax at a rate of 0.000000. Which texts set that rate?', '["PIA s.267(b), which gives frontier acreage a rate of 0 percent", "Seventh Schedule para 11(2), since frontier pays no royalty by price and so no hydrocarbon tax either", "A stated reading of an open question", "PIA s.260(3) and NTA s.65(4), until the acreage is reclassified"]'::jsonb, 3, 'PIA s.260(3) keeps frontier acreage outside the Part "until it is reclassified under section 68 (3)", and NTA s.65(4) keeps the same carve-out, so the engine returns 0.000000 under either framework. Section 267(b) is the 15 percent class. Para 11(2) removes the royalty by price and says nothing about the tax. The frontier rate is printed in both texts and is no open reading.'),
  ('pia', 'intermediate', 'final', null, 10, 'The Ekene marginal field is a shallow water lease converted under s.94(1). Its hydrocarbon tax rate is 0.150000. Which provisions give that rate?', '["PIA s.94(1) with s.267(b)", "PIA s.267(a) alone", "Seventh Schedule para 10(4)", "A stated new-lease reading"]'::jsonb, 0, 'Section 94(1) has a producing marginal field convert to a petroleum mining lease on the terms of s.267(b) and s.302, and s.267(b) is the 15 percent class; the engine takes it as the stated flag pia_marginal_field_pre_2021. Section 267(a) is the 30 percent class. Para 10(4) is royalty and sets the tranches this field pays (0.093750 at 20000 bopd), and it sets no tax rate. The flag is on a converted lease, so no new-lease reading arises.'),
  ('pia', 'intermediate', 'final', null, 11, 'Which response does the engine give to a licence type of "OML"?', '["It refuses: \"pia_license_type must be \"PML\" or \"PPL\"; got \"OML\".\"", "The old oil mining lease terms are applied, as the licence has not converted", "OML is read as a converted PML and taxed at the 30 percent class", "A run at 15 percent, the rate of a licence from before the Act"]'::jsonb, 0, 'An oil mining lease is a licence type from before the Act, and the engine accepts "PML" or "PPL" only, refusing anything else in its own words. The engine models converted and new-acreage terms only, so the old terms are concept-only. It never maps one licence type to another silently, and a refusal returns no rate at all.'),
  ('pia', 'intermediate', 'final', null, 12, 'A lease status of "renewed" is typed into the terms. What comes back?', '["Converted-lease terms, since the Sixth Schedule para 1(1) names converted leases and their renewals", "New-lease terms, since a renewal is a fresh grant after the Act commenced", "A refusal: \"pia_lease_status must be \"converted\" or \"new\"; got \"renewed\".\"", "A result with the production allowance set to zero and a note"]'::jsonb, 2, 'The engine takes the lease status as one of two stated strings and refuses any other in its own words. Para 1(1) does mention renewals of converted leases, but the engine reads only "converted" or "new", so the learner states which one applies. It never guesses a status, and a refusal returns no allowance or note.'),
  ('pia', 'intermediate', 'final', null, 13, 'On the Ekene new onshore lease in 2027, the chargeable profit is 123946029.235482 under both stated readings. What are the 2027 hydrocarbon tax figures?', '["37183808.770645 under both readings, since the chargeable profit is the same", "18591904.385322 at the stated 15 and 37183808.770645 at the stated 30", "18591904.385322 under both readings, with the stated 30 moving companies income tax", "40183808.770645 at the stated 15 and 18591904.385322 at the stated 30, one halving the other"]'::jsonb, 1, 'The stated rate moves only the tax line: 15 percent gives 18591904.385322 and 30 percent 37183808.770645, on the same chargeable profit. The same base does not make the same tax; the rate differs. Companies income tax is 40183808.770645 under both readings, because it does not deduct the hydrocarbon tax, so it is neither moved by the reading nor a hydrocarbon tax figure.'),
  ('pia', 'intermediate', 'final', null, 14, 'An override of 150 is stated for the hydrocarbon tax rate. How does the engine handle it?', '["Tax charged at 150 percent of chargeable profit, the rate as stated", "The capped rate of 100 percent", "A refusal naming the range the override must sit in", "The s.267 rate for the lease, with the stated override ignored"]'::jsonb, 2, 'The engine''s words are: "pia_hct_rate_override_pct must be a number from 0 to 100; got 150." Out of range means no run at all: the engine does not charge 150 percent, cap the figure at 100 or fall back to the s.267 class. The learner corrects the terms and runs again.'),
  ('pia', 'intermediate', 'final', null, 15, 'On the Ekene CPR case, 2025 HCDT is 1200000.000000 and the 2025 NDDC levy is also 1200000.000000. What does each read?', '["Each reads the 2025 opex at 3 percent, which is why the two lines print the same figure", "HCDT reads the 2024 opex; the levy reads the 2025 opex plus capex", "The 2024 opex plus capex, for both", "Revenue for HCDT and royalty for the levy"]'::jsonb, 1, 'HCDT is 3 percent of the preceding year''s opex (40000000 USD in 2024), and the NDDC levy is 3 percent of the year''s opex plus capex (40000000 USD of opex and no capex in 2025). The two happen to print alike here and read different bases: in 2024 HCDT is 0.000000 with no prior year stated, while the levy is 5700000.000000 because the 2024 capex enters its base. Neither reads revenue or royalty.'),
  ('pia', 'intermediate', 'final', null, 16, 'PIA s.263(1)(f) names which deductions for the hydrocarbon tax?', '["Companies income tax and the tertiary education tax paid in the same period, as taxes owed to the Federal Government", "Signature and production bonuses paid for petroleum rights", "Cost still above the cost price ratio at cessation", "Levies, stamp duties and fees owed to the Federal, State or Local Government"]'::jsonb, 3, 'The text reads: "(f ) all sums the liability of which was incurred by the company to the Federal Government or any State or Local Government Council by way of levies, stamp duties and fees ;". Companies income tax and the tertiary education tax are barred by s.264(l). Bonuses are barred by s.264(f), a concept-only item since the engine takes no bonus input. Cost above the cap at cessation is barred by s.264(q).'),
  ('pia', 'intermediate', 'final', null, 17, 'PIA s.263(1)(e) makes a decommissioning and abandonment fund contribution deductible. What condition does the text attach?', '["The fund''s surplus or residue is taxed at the end of the field''s life", "The contribution is deductible only above 65 percent of revenue, as the part the cost price ratio cannot hold", "Only half the contribution may be deducted", "It is deductible for companies income tax only"]'::jsonb, 0, 'The text allows "any amount contributed to a fund, scheme or arrangement approved by the Commission for the purpose of decommissioning and abandonment, provided that the surplus or residue of the fund shall be subject to tax under this Act at the end of life of the field,". The engine counts the contribution inside the cost price ratio pool; it is never a threshold above 65 percent. Nothing halves it, and s.302(11)(b) makes it deductible for companies income tax as well.'),
  ('pia', 'intermediate', 'final', null, 18, 'PIA s.264(f) bars signature, production and renewal bonuses from the hydrocarbon tax base. How does the course treat that item?', '["As concept-only, since the engine takes no bonus input", "Graded, read from the bonus column of the tax base view, since the engine prints every deduction the Act names", "Deducted by the engine under s.263(1)(f)", "Refused whenever a bonus appears"]'::jsonb, 0, 'The engine has no input for a bonus, so the bar in s.264(f) is taught from its text and never graded on a number. No bonus column exists. Section 263(1)(f) covers levies, stamp duties and fees, and s.264(f) keeps bonuses out explicitly. With no bonus input, there is nothing for the engine to refuse.'),
  ('pia', 'intermediate', 'final', null, 19, 'On the Ekene CPR case in 2026 the hydrocarbon tax assessable profit is 10292934.782609 and the chargeable profit 8792934.782609. What came off between them?', '["The capital allowance of the 2024 spend for 2026, in full, beside the production allowance", "The carried pool of 93000000.000000, released against the profit in the ledger''s last year", "HCDT and the NDDC levy, 1200000.000000 each, taken at the chargeable step", "The production allowance of 1500000.000000, with no capital allowance let through that year"]'::jsonb, 3, 'The step deducts the capital allowance the cap let through and the production allowance. The gap between the two lines is exactly the production allowance, 1500000.000000, so the cap, full of carried cost and opex, let no capital allowance through in 2026. The carried pool of 93000000.000000 is what the cap turned away and is forfeited at cessation. HCDT and the NDDC levy come off before the assessable profit.'),
  ('pia', 'intermediate', 'final', null, 20, 'The Nigeria Tax Act 2025 prints the cost price ratio at its Sixth Schedule para 2(1). What does its text measure the 65 percent against?', '["Total costs incurred, capital and operating together", "Gross revenues determined at the measurement points", "The previous year''s revenue", "Revenue after royalties and levies"]'::jsonb, 1, 'The NTA text caps deductions at "a cost price ratio limit of 65% of gross revenues determined at the measurement points." The limit is on revenue, so a share of costs would have nothing to cap. Nothing in either text reads the previous year''s revenue or nets royalties first; royalties sit outside the cap altogether.'),
  ('pia', 'intermediate', 'final', null, 21, 'Between 2026 and 2027 the limit on Alpha''s cost recovery drops from 147664400.000000 to 129944672.000000. What drives the drop?', '["The carried pool shrinks the cap a little more in each year that follows", "Capex falls from 120000000 USD to 30000000 USD, and the cap is a share of costs", "Gas revenue grows, and the cap deducts it", "Alpha''s crude oil and condensate revenue falls as the field declines, and the cap is 65 percent of it"]'::jsonb, 3, 'Para 2(1) sets the limit at 65 percent of gross revenues, which the engine reads as crude oil and condensate revenue, so a declining field has a falling cap. Alpha carries nothing, and no carry reduces a cap in any case. The cap is measured on revenue; capex enters the pool it limits and plays no part in the limit. Gas revenue never enters the cap and is not deducted from it; Alpha''s gas declines with its crude.'),
  ('pia', 'intermediate', 'final', null, 22, 'Under the Nigeria Tax Act 2025, First Schedule Part II para 4(2) records 1 percent of qualifying capital expenditure. What effect does that record have on the allowance claimed?', '["Holds back 1 percent of each spend until disposal, as the Act''s para 5(2) does", "Adds 1 percent to the fifth-year rate, lifting it above 20 percent", "Each year''s rate falls to 19 percent", "None: it is a notional amount"]'::jsonb, 3, 'Para 4(2) says the 1 percent is recorded "for statistical purposes until the asset is disposed" and, "being a notional amount, shall not increase or reduce the amount of capital allowance claimable under this Part." The Act''s para 5(2) retains 1 percent in the books; the NTA record does not. Neither text lifts a rate above 20 percent, and 19 percent is the Act''s fifth-year rate alone.'),
  ('pia', 'intermediate', 'final', null, 23, 'A new shallow water lease has produced 99500000 barrels before a year under the Act alone and then produces 1000000 barrels at 75 USD/bbl. What does the engine return?', '["8000000.000000, as the shallow water cap is 500 million barrels", "6000000.000000, split 500000 barrels either side of the 100 million barrel cap", "4000000.000000, as the onshore cap of 50 million is passed", "2500000.000000"]'::jsonb, 1, 'Para 1(2)(b) runs the first tier "up to a cumulative maximum production of 100 million barrels" for shallow water, so the year splits: 500000 barrels at 8.00 USD and 500000 at 4.00 USD. The 500 million barrel cap is for deep offshore and frontier. The 50 million cap is onshore. 2500000.000000 would be the converted-lease allowance, and this lease is new.'),
  ('pia', 'intermediate', 'final', null, 24, 'A new onshore lease is past its cap, and the oil price is 15 USD/bbl. What allowance does the engine give 1000000 barrels?', '["4000000.000000, the second tier", "2500000.000000, the converted leg", "8000000.000000, the first tier", "3000000.000000"]'::jsonb, 3, 'After the cap each barrel earns the lower of 4.00 USD and 20 percent of the price; at 15 USD/bbl, 20 percent is lower, so 1000000 barrels earn 3000000.000000. 4000000.000000 is the return at 75 USD/bbl, where 4.00 USD is the lower leg. The converted-lease allowance does not apply to a new lease, and no price restores the first tier.'),
  ('pia', 'intermediate', 'final', null, 25, 'PIA Sixth Schedule para 1(4) extends the production allowance. To what?', '["Condensates and liquid natural gas liquids within the tax under s.260(1)(a)", "Natural gas sold in-country at the 2.5 percent royalty rate, as gas is the other stream a field sells", "Non-associated gas condensate, which para 1(4) brings back into the tax base", "Capital spending, as a second capital allowance"]'::jsonb, 0, 'The text reads: "(4) Any allowances for crude oil shall also apply to condensates and liquid natural gas liquids under section 260 (1) (a) of this Act." Gas is outside the tax and earns no allowance. Non-associated gas condensate is outside the tax under s.260(1)(b)(ii), and para 1(4) points only to s.260(1)(a). The production allowance is a sum per barrel and has nothing to do with capital spending.'),
  ('pia', 'intermediate', 'final', null, 26, 'Does the converted-lease production allowance differ between a year under the Act alone and a year under the Nigeria Tax Act 2025?', '["Yes: the NTA raises the fixed leg to 8.00 USD for converted leases that renew after 2026", "No, both texts print the same paragraph", "The NTA drops the allowance for converted leases in shallow water, so it differs", "It differs, as the NTA halves the 20 percent price leg"]'::jsonb, 1, 'The Act''s Sixth Schedule para 1(1) and the NTA''s Sixth Schedule para 1(1) both give converted leases "the lower of US $2.50 per barrel and 20% of the fiscal oil price", so the engine returns the same allowance in every year it reads. The 8.00 USD leg belongs to new leases. Neither text drops or halves the converted-lease allowance.'),
  ('pia', 'intermediate', 'final', null, 27, 'The worked example''s converted lease earns a production allowance of 45625000.000000 on 18250000 barrels at 80 USD/bbl. What would happen to it if the oil price were 10 USD/bbl?', '["Nothing: a converted lease earns 2.50 USD a barrel at any price", "A rise to the 8.00 USD first tier", "Zero, since the allowance stops below 12.50 USD/bbl", "It would fall, since 20 percent of the price drops below 2.50 USD"]'::jsonb, 3, 'The converted-lease allowance is the lower of 2.50 USD and 20 percent of the price. At 80 USD/bbl the fixed leg is lower; at 10 USD/bbl the price leg is lower, and on 1000000 barrels the engine returns 2000000.000000 at that price. The 8.00 USD tier is for new leases. The allowance does not stop below the crossing price of 12.50 USD/bbl; the price leg simply takes over.'),
  ('pia', 'intermediate', 'final', null, 28, 'Which cumulative production cap does PIA Sixth Schedule para 1(2)(c) set for deep offshore and frontier leases granted after the Act?', '["50 million barrels, the same as onshore, since para 1(2) sets one cap for every terrain", "500 million barrels", "100 million barrels, the same as shallow water", "No cap at all"]'::jsonb, 1, 'Para 1(2)(c) gives "the lower of US $8.00 per barrel and 20% of the fiscal oil price, up to a cumulative maximum production of 500 million barrels". The onshore cap is 50 million and the shallow water cap 100 million, each set in its own paragraph. The first tier ends at the cap on every terrain.'),
  ('pia', 'intermediate', 'final', null, 29, 'The course reads the Finance Act 2023 for the two thirds restriction. How is that text used?', '["Quoted verbatim, like the gazetted Act", "Taken from a paid commentary, quoted with its citation", "Paraphrased, as it was read from a scanned copy", "Not used; the engine sets the restriction itself"]'::jsonb, 2, 'The Finance Act 2023 was read as the "Final Signed by PMB" copy published by the Budget Office of the Federation on 7 June 2023, a scan read page by page, so the course paraphrases it. Only public texts are quoted, and paid commentary is never quoted. The restriction the engine applies is the one the Act''s s.9(b) substitutes into CITA para 24(7).'),
  ('pia', 'intermediate', 'final', null, 30, 'PIA s.302(11)(b) lets companies income tax deduct contributions to approved funds. Which purposes does it name?', '["Decommissioning, host communities trusts and environmental remediation", "Only decommissioning funds, and only once production from the field has ended", "Royalties on crude oil, condensate and natural gas", "The Niger Delta Development Commission alone"]'::jsonb, 0, 'The text names funds "for the purpose of providing for: (i) abandonment and decommissioning, (ii) petroleum host communities development trust, or (iii) environmental remediation ;". The text names three purposes and ties none of them to the end of production. Royalties are deducted under s.302(11)(a). The NDDC levy is deducted in the engine''s base as well, but it is not what (b) names.'),
  ('pia', 'intermediate', 'final', null, 31, 'What does NTA s.78(3)(a) say about the hydrocarbon tax in computing income tax under Chapter Two?', '["Fully deductible", "That it is not deductible", "Half of it may be deducted", "It replaces income tax for crude oil"]'::jsonb, 1, 'The text reads: "(3) In determining the income tax under Chapter Two of this Act: (a) hydrocarbon tax is not deductible; and", the same rule as PIA s.302(5). So the two taxes run in parallel and neither deducts the other, in full or in part, and neither replaces the other.'),
  ('pia', 'intermediate', 'final', null, 32, 'What companies income tax does the Ekene onshore lease pay in 2024, a year under the Act alone, when its assessable profit for that tax is 153422584.102902?', '["30 percent of the whole assessable profit, with no capital allowance deducted", "40626775.230871", "36126841.671286, the figure the next year returns", "83939977.984829, the total tax"]'::jsonb, 1, 'The engine claims the 18000000.000000 capital allowance (two thirds of the assessable profit is larger, so the restriction does not bind) and charges 30 percent on the rest, 40626775.230871. Thirty percent of the whole assessable profit leaves the allowance in the base. 36126841.671286 is the 2025 companies income tax. 83939977.984829 is total tax, which adds the other instruments.'),
  ('pia', 'intermediate', 'final', null, 33, 'Under the two thirds restriction, how much capital allowance does the CPR case claim in 2025, when its assessable profit for companies income tax is 13442572.062084?', '["13442572.062084, the whole assessable profit", "The whole allowance, since the restriction ended in 2024", "8961714.708056, two thirds of the assessable profit", "Nothing, since the cost price ratio already took the allowance"]'::jsonb, 2, 'The two thirds restriction applies in every year under the Act alone, so the claim is two thirds of 13442572.062084, 8961714.708056, and the rest is carried. Claiming the whole profit would ignore the limit. The rule is in force in 2025 as in 2024. The cost price ratio belongs to the hydrocarbon tax and leaves the companies income tax allowance alone.'),
  ('pia', 'intermediate', 'final', null, 34, 'PIA s.265(1) defines assessable profit for the hydrocarbon tax. What does it deduct from the adjusted profit?', '["Any loss incurred in a previous accounting period", "A loss the company expects to make in the next accounting period", "The hydrocarbon tax paid in the previous accounting period", "Every cost above the cost price ratio"]'::jsonb, 0, 'The text reads: "that period after the deduction of the amount of any loss incurred by that company during any previous accounting period." Losses run forward from earlier periods and none comes back from a later one. The tax itself is not a deduction. Cost above the cap is a cost price ratio carry, a different rule with its own forfeiture.'),
  ('pia', 'intermediate', 'final', null, 35, 'On the Ekene CPR case the 2026 companies income tax is 0.000000. Why?', '["The two thirds restriction removes the whole profit, leaving nothing to tax", "The hydrocarbon tax of 2026 is deducted first", "The chargeable profit is below zero, so the year carries a loss", "Companies income tax is suspended in any year when the cost price ratio cap binds"]'::jsonb, 2, 'The 2026 companies income tax chargeable profit is -65495752.569896, so the tax is 0.000000 and the loss is carried. The restriction limits the allowance and leaves the profit alone, and companies income tax does not deduct the hydrocarbon tax. No rule suspends one tax when the other''s cap binds.'),
  ('pia', 'intermediate', 'final', null, 36, 'The worked example''s gross revenue is 1,460,000,000.000000. Which provision puts every dollar of it inside the hydrocarbon tax?', '["Seventh Schedule para 6, which treats every stream as crude oil", "PIA s.260(1)(a), since the year is crude oil only", "Sixth Schedule para 2(1), which reads gross revenue", "PIA s.263(1)(b)"]'::jsonb, 1, 'Section 260(1)(a) brings crude oil into the tax, and the worked example sells crude oil only, so all of its revenue is in the base. Para 6 treats condensate as crude oil for royalty and natural gas liquids as gas. Para 2(1) sets the cap on revenue and puts nothing into the tax. Section 263(1)(b) deducts royalties.'),
  ('pia', 'intermediate', 'final', null, 37, 'A ledger returns with a note in kpis.pia_notes. Another run stops with a thrown message. How should each be read?', '["The note is part of a result; the message names an input to fix in the terms", "Warnings, both of them, on a finished ledger", "Both are refusals", "An error in the note, and a warning in the message"]'::jsonb, 0, 'A note is a statement the engine attaches to a finished result about a stated default, a conflict between texts or an approximation. A refusal is a thrown error with no result, and its message states the exact condition that failed, so the fix is in the terms. Neither reading of both as the same kind of output holds.'),
  ('pia', 'intermediate', 'final', null, 38, 'On Ekene Alpha in 2026 the cost price ratio claim is 46563591.022444 and the HCT assessable profit 182041059.069891. Which provision decides that the claim holds only part of the opex?', '["The 65 percent cap of para 2(1), which binds on Alpha in 2026", "The two thirds restriction of CITA para 24(7)", "The shared-costs split at the crude-plus-condensate share", "The Sixth Schedule production allowance"]'::jsonb, 2, 'Alpha sells gas, so opex and the other shared costs enter the tax at the 0.970075 liquids share; the claim is far below the cap of 147664400.000000, so the cap does not bind. The two thirds restriction limits the companies income tax allowance. The production allowance is a per-barrel deduction below the assessable line and is not part of the claim.'),
  ('pia', 'intermediate', 'final', null, 39, 'Ekene Alpha''s hydrocarbon tax over its life is 204770583.587056 at 100 percent and 102385291.793528 at 50 percent. What does the pair show?', '["Half the barrels feed the tranches", "Money lines scale to the share after field-level arithmetic", "A lower rate for the 50 percent partner", "The cap binds at 50 percent"]'::jsonb, 1, 'The course checks that at 50 percent every money line is exactly half, and the hydrocarbon tax pair shows it. The engine does the fiscal arithmetic on the whole field first, so the tranches see every barrel and the s.267 class is the lease''s whatever the share. Alpha''s cost price ratio never binds, at either share.'),
  ('pia', 'intermediate', 'final', null, 40, 'The Professional reading names the cash flow course for some of the work. Which of these belongs to that course?', '["Forfeiture of cost under the Sixth Schedule cap at the end of the ledger", "Classes of rate under s.267", "The production allowance tiers and the barrels either side of the cap", "Discounting, NPV, IRR and the arithmetic of carrying pools"]'::jsonb, 3, 'The cash flow course owns the ledger arithmetic: discounting, NPV, IRR, payback, the order of the ledger rows, loss-pool arithmetic and working-interest scaling. This course names the provision behind a line: the cap and its forfeiture, the rate classes and the allowance tiers are all taught here.'),
  ('pia', 'intermediate', 'final', null, 41, 'The fiscal course is named at the seam of this one. What does it own?', '["Teaching the Act''s hydrocarbon tax as a system", "Ekene cases", "Regime design in the abstract: instruments, sliding scales and R-factors", "The royalty tranches of the Seventh Schedule"]'::jsonb, 2, 'Fiscal regime design belongs to the fiscal course: the four instruments in the abstract, sliding scales, R-factors, templates and progressivity. This course teaches the Act as a system, with its own Ekene cases and the gazetted tranches.'),
  ('pia', 'intermediate', 'final', null, 42, 'The engine accepts pia_gas_in_country_share_pct 100. What gas royalty rate results?', '["0.050000, as export gas", "0.037500, a half blend", "A refusal at the edge", "0.025000"]'::jsonb, 3, 'The in-country share runs from 0 to 100 inclusive, and at 100 every unit of gas pays the 2.5 percent in-country rate, 0.025000. 0.050000 is the rate at a share of 0. 0.037500 is the blend at 50. The engine refuses only above 100, such as 100.5.');
